        return ByteBuffer.allocate(size);
    });
    ByteBuffersDataOutput o = new ByteBuffersDataOutput(ByteBuffersDataOutput.DEFAULT_MIN_BITS_PER_BLOCK, ByteBuffersDataOutput.DEFAULT_MAX_BITS_PER_BLOCK, reuser::allocate, reuser::reuse);
