        if (!me.subpath(me.length - 1).equals(parent)) {
            fail("Got parent " + parentOrdinal + " for ordinal " + ordinal + " but categories are " + showcat(parent) + " and " + showcat(me) + " respectively.");
        }
    }
    tr.close();
    indexDir.close();
}

