    List<RevisionFile> files1 = session1.sourceFiles.values().iterator().next();
    List<RevisionFile> files2 = session2.sourceFiles.values().iterator().next();
    assertEquals(files1, files2);
    writer.close();
    IOUtils.close(dir);
}

