        int i = j % INT;
        long l = j % LONG;
        float f = j % FLOAT;
        double d = j % DOUBLE;
        int dt = j % DATE;
        int s = j % STRING;
        assertU(adoc("id", "1000" + j, "int_id", "" + i, "long_ld", "" + l, "float_fd", "" + f, "double_dd", "" + d, "date_dtd", (1800 + dt) + "-12-31T23:59:59.999Z", "string_sd", "abc" + Integer.toString(s).charAt(0)));
