    for (int i = 0; i < shortSummaryClusters.size(); i++) {
        assertTrue("Summary shorter than original document", getLabels(shortSummaryClusters.get(i)).get(1).length() < getLabels(longSummaryClusters.get(i)).get(1).length());
    }
}

