@Test
public void templateXPath() {
    DataImporter di = new DataImporter();
    di.loadAndInit(dc_variableXpath);
    DIHConfiguration cfg = di.getConfig();
    RequestInfo rp = new RequestInfo(null, createMap("command", "full-import"), null);
