@Test
public void testOverridesAbstractScorerMethods() {
    final Class<?> ossClass = OriginalScoreFeature.OriginalScoreWeight.OriginalScoreScorer.class;
    for (final Method scorerClassMethod : Scorer.class.getDeclaredMethods()) {
        final int modifiers = scorerClassMethod.getModifiers();
        if (!Modifier.isAbstract(modifiers))
            continue;
        try {
            final Method ossClassMethod = ossClass.getDeclaredMethod(scorerClassMethod.getName(), scorerClassMethod.getParameterTypes());
            assertEquals("getReturnType() difference", scorerClassMethod.getReturnType(), ossClassMethod.getReturnType());
        } catch (NoSuchMethodException e) {
            fail(ossClass + " needs to override '" + scorerClassMethod + "'");
        }
    }
}

@Test
public void testRankingSolrFeature() throws Exception {
    // before();
    loadFeature("powpularityS", SolrFeature.class.getName(), "{\"q\":\"{!func}pow(popularity,2)\"}");
    loadFeature("unpopularityS", SolrFeature.class.getName(), "{\"q\":\"{!func}div(1,popularity)\"}");
    loadModel("powpularityS-model", LinearModel.class.getName(), new String[] { "powpularityS" }, "{\"weights\":{\"powpularityS\":1.0}}");
    loadModel("unpopularityS-model", LinearModel.class.getName(), new String[] { "unpopularityS" }, "{\"weights\":{\"unpopularityS\":1.0}}");
    final SolrQuery query = new SolrQuery();
    query.setQuery("title:w1");
    query.add("fl", "*, score");
    query.add("rows", "4");
    assertJQ("/query" + query.toQueryString(), "/response/numFound/==4");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/id=='1'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[1]/id=='8'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[2]/id=='6'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[3]/id=='7'");
    // Normal term match
    query.add("rq", "{!ltr model=powpularityS-model reRankDocs=4}");
    query.set("debugQuery", "on");
    assertJQ("/query" + query.toQueryString(), "/response/numFound/==4");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/id=='8'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/score==64.0");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[1]/id=='7'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[1]/score==49.0");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[2]/id=='6'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[2]/score==36.0");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[3]/id=='1'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[3]/score==1.0");
    query.remove("rq");
    query.add("rq", "{!ltr model=unpopularityS-model reRankDocs=4}");
    assertJQ("/query" + query.toQueryString(), "/response/numFound/==4");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/id=='1'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[0]/score==1.0");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[1]/id=='6'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[2]/id=='7'");
    assertJQ("/query" + query.toQueryString(), "/response/docs/[3]/id=='8'");
    //bad solr ranking feature
    loadFeature("powdesS", SolrFeature.class.getName(), "{\"q\":\"{!func}pow(description,2)\"}");
    loadModel("powdesS-model", LinearModel.class.getName(), new String[] { "powdesS" }, "{\"weights\":{\"powdesS\":1.0}}");
    query.remove("rq");
    query.add("rq", "{!ltr model=powdesS-model reRankDocs=4}");
    assertJQ("/query" + query.toQueryString(), "/error/msg/=='" + FeatureException.class.getName() + ": " + "java.lang.UnsupportedOperationException: " + "Unable to extract feature for powdesS'");
}

