@Test
public void testAddMultipleReplicas() throws Exception {
    String collection = "testAddMultipleReplicas";
    CloudSolrClient cloudClient = cluster.getSolrClient();
    CollectionAdminRequest.Create create = CollectionAdminRequest.createCollection(collection, "conf1", 1, 1);
    create.setMaxShardsPerNode(2);
    cloudClient.request(create);
    cluster.waitForActiveCollection(collection, 1, 1);
    CollectionAdminRequest.AddReplica addReplica = CollectionAdminRequest.addReplicaToShard(collection, "shard1").setNrtReplicas(1).setTlogReplicas(1).setPullReplicas(1);
    RequestStatusState status = addReplica.processAndWait(collection + "_xyz1", cloudClient, 120);
    assertEquals(COMPLETED, status);
    cluster.waitForActiveCollection(collection, 1, 4);
    DocCollection docCollection = cloudClient.getZkStateReader().getClusterState().getCollectionOrNull(collection);
    assertNotNull(docCollection);
    assertEquals(4, docCollection.getReplicas().size());
    assertEquals(2, docCollection.getReplicas(EnumSet.of(Replica.Type.NRT)).size());
    assertEquals(1, docCollection.getReplicas(EnumSet.of(Replica.Type.TLOG)).size());
    assertEquals(1, docCollection.getReplicas(EnumSet.of(Replica.Type.PULL)).size());
    // try to add 5 more replicas which should fail because numNodes(4)*maxShardsPerNode(2)=8 and 4 replicas already exist
    addReplica = CollectionAdminRequest.addReplicaToShard(collection, "shard1").setNrtReplicas(3).setTlogReplicas(1).setPullReplicas(1);
    status = addReplica.processAndWait(collection + "_xyz1", cloudClient, 120);
    assertEquals(FAILED, status);
    docCollection = cloudClient.getZkStateReader().getClusterState().getCollectionOrNull(collection);
    assertNotNull(docCollection);
    // sanity check that everything is as before
    assertEquals(4, docCollection.getReplicas().size());
    assertEquals(2, docCollection.getReplicas(EnumSet.of(Replica.Type.NRT)).size());
    assertEquals(1, docCollection.getReplicas(EnumSet.of(Replica.Type.TLOG)).size());
    assertEquals(1, docCollection.getReplicas(EnumSet.of(Replica.Type.PULL)).size());
    // but adding any number of replicas is supported if an explicit create node set is specified
    // so test that as well
    LinkedHashSet<String> createNodeSet = new LinkedHashSet<>(2);
    createNodeSet.add(cluster.getRandomJetty(random()).getNodeName());
    while (true) {
        String nodeName = cluster.getRandomJetty(random()).getNodeName();
        if (createNodeSet.add(nodeName))
            break;
    }
    addReplica = CollectionAdminRequest.addReplicaToShard(collection, "shard1").setNrtReplicas(3).setTlogReplicas(1).setPullReplicas(1).setCreateNodeSet(String.join(",", createNodeSet));
    status = addReplica.processAndWait(collection + "_xyz1", cloudClient, 120);
    assertEquals(COMPLETED, status);
    waitForState("Timedout wait for collection to be created", collection, clusterShape(1, 9));
    docCollection = cloudClient.getZkStateReader().getClusterState().getCollectionOrNull(collection);
    assertNotNull(docCollection);
    // sanity check that everything is as before
    assertEquals(9, docCollection.getReplicas().size());
    assertEquals(5, docCollection.getReplicas(EnumSet.of(Replica.Type.NRT)).size());
    assertEquals(2, docCollection.getReplicas(EnumSet.of(Replica.Type.TLOG)).size());
    assertEquals(2, docCollection.getReplicas(EnumSet.of(Replica.Type.PULL)).size());
}

@Test
public void test() throws Exception {
    String collection = "addreplicatest_coll";
    CloudSolrClient cloudClient = cluster.getSolrClient();
    CollectionAdminRequest.Create create = CollectionAdminRequest.createCollection(collection, "conf1", 2, 1);
    create.setMaxShardsPerNode(2);
    cloudClient.request(create);
    cluster.waitForActiveCollection(collection, 2, 2);
    ClusterState clusterState = cloudClient.getZkStateReader().getClusterState();
    DocCollection coll = clusterState.getCollection(collection);
    String sliceName = coll.getSlices().iterator().next().getName();
    Collection<Replica> replicas = coll.getSlice(sliceName).getReplicas();
    CollectionAdminRequest.AddReplica addReplica = CollectionAdminRequest.addReplicaToShard(collection, sliceName);
    addReplica.processAsync("000", cloudClient);
    CollectionAdminRequest.RequestStatus requestStatus = CollectionAdminRequest.requestStatus("000");
    CollectionAdminRequest.RequestStatusResponse rsp = requestStatus.process(cloudClient);
    assertNotSame(rsp.getRequestStatus(), COMPLETED);
    // wait for async request success
    boolean success = false;
    for (int i = 0; i < 200; i++) {
        rsp = requestStatus.process(cloudClient);
        if (rsp.getRequestStatus() == COMPLETED) {
            success = true;
            break;
        }
        assertNotSame(rsp.toString(), rsp.getRequestStatus(), RequestStatusState.FAILED);
        Thread.sleep(500);
    }
    assertTrue(success);
    Collection<Replica> replicas2 = cloudClient.getZkStateReader().getClusterState().getCollection(collection).getSlice(sliceName).getReplicas();
    replicas2.removeAll(replicas);
    assertEquals(1, replicas2.size());
    // use waitForFinalState
    addReplica.setWaitForFinalState(true);
    addReplica.processAsync("001", cloudClient);
    requestStatus = CollectionAdminRequest.requestStatus("001");
    rsp = requestStatus.process(cloudClient);
    assertNotSame(rsp.getRequestStatus(), COMPLETED);
    // wait for async request success
    success = false;
    for (int i = 0; i < 200; i++) {
        rsp = requestStatus.process(cloudClient);
        if (rsp.getRequestStatus() == COMPLETED) {
            success = true;
            break;
        }
        assertNotSame(rsp.toString(), rsp.getRequestStatus(), RequestStatusState.FAILED);
        Thread.sleep(500);
    }
    assertTrue(success);
    // let the client watch fire
    Thread.sleep(1000);
    clusterState = cloudClient.getZkStateReader().getClusterState();
    coll = clusterState.getCollection(collection);
    Collection<Replica> replicas3 = coll.getSlice(sliceName).getReplicas();
    replicas3.removeAll(replicas);
    String replica2 = replicas2.iterator().next().getName();
    assertEquals(2, replicas3.size());
    for (Replica replica : replicas3) {
        if (replica.getName().equals(replica2)) {
            // may be still recovering
            continue;
        }
        assertSame(coll.toString() + "\n" + replica.toString(), replica.getState(), Replica.State.ACTIVE);
    }
}

@Test
public void testProperties() throws Exception {
    CollectionAdminRequest.createCollection("collection1meta", "conf", 2, 1).process(cluster.getSolrClient());
    CollectionAdminRequest.createCollection("collection2meta", "conf", 1, 1).process(cluster.getSolrClient());
    cluster.waitForActiveCollection("collection1meta", 2, 2);
    cluster.waitForActiveCollection("collection2meta", 1, 1);
    waitForState("Expected collection1 to be created with 2 shards and 1 replica", "collection1meta", clusterShape(2, 2));
    waitForState("Expected collection2 to be created with 1 shard and 1 replica", "collection2meta", clusterShape(1, 1));
    ZkStateReader zkStateReader = cluster.getSolrClient().getZkStateReader();
    zkStateReader.createClusterStateWatchersAndUpdate();
    List<String> aliases = zkStateReader.getAliases().resolveAliases("meta1");
    assertEquals(1, aliases.size());
    assertEquals("meta1", aliases.get(0));
    final ZkStateReader.AliasesManager aliasesManager = zkStateReader.aliasesManager;
    aliasesManager.applyModificationAndExportToZk(a -> a.cloneWithCollectionAlias("meta1", "collection1meta,collection2meta"));
    aliases = zkStateReader.getAliases().resolveAliases("meta1");
    assertEquals(2, aliases.size());
    assertEquals("collection1meta", aliases.get(0));
    assertEquals("collection2meta", aliases.get(1));
    //ensure we have the back-compat format in ZK:
    final byte[] rawBytes = zkStateReader.getZkClient().getData(ALIASES, null, null, true);
    //noinspection unchecked
    assertTrue(((Map<String, Map<String, ?>>) Utils.fromJSON(rawBytes)).get("collection").get("meta1") instanceof String);
    // set properties
    aliasesManager.applyModificationAndExportToZk(a1 -> a1.cloneWithCollectionAliasProperties("meta1", "foo", "bar"));
    Map<String, String> meta = zkStateReader.getAliases().getCollectionAliasProperties("meta1");
    assertNotNull(meta);
    assertTrue(meta.containsKey("foo"));
    assertEquals("bar", meta.get("foo"));
    // set more properties
    aliasesManager.applyModificationAndExportToZk(a1 -> a1.cloneWithCollectionAliasProperties("meta1", "foobar", "bazbam"));
    meta = zkStateReader.getAliases().getCollectionAliasProperties("meta1");
    assertNotNull(meta);
    // old properties still there
    assertTrue(meta.containsKey("foo"));
    assertEquals("bar", meta.get("foo"));
    // new properties added
    assertTrue(meta.containsKey("foobar"));
    assertEquals("bazbam", meta.get("foobar"));
    // remove properties
    aliasesManager.applyModificationAndExportToZk(a1 -> a1.cloneWithCollectionAliasProperties("meta1", "foo", null));
    meta = zkStateReader.getAliases().getCollectionAliasProperties("meta1");
    assertNotNull(meta);
    // verify key was removed
    assertFalse(meta.containsKey("foo"));
    // but only the specified key was removed
    assertTrue(meta.containsKey("foobar"));
    assertEquals("bazbam", meta.get("foobar"));
    // removal of non existent key should succeed.
    aliasesManager.applyModificationAndExportToZk(a2 -> a2.cloneWithCollectionAliasProperties("meta1", "foo", null));
    // chained invocations
    aliasesManager.applyModificationAndExportToZk(a1 -> a1.cloneWithCollectionAliasProperties("meta1", "foo2", "bazbam").cloneWithCollectionAliasProperties("meta1", "foo3", "bazbam2"));
    // some other independent update (not overwritten)
    aliasesManager.applyModificationAndExportToZk(a1 -> a1.cloneWithCollectionAlias("meta3", "collection1meta,collection2meta"));
    // competing went through
    assertEquals("collection1meta,collection2meta", zkStateReader.getAliases().getCollectionAliasMap().get("meta3"));
    meta = zkStateReader.getAliases().getCollectionAliasProperties("meta1");
    assertNotNull(meta);
    // old properties still there
    assertTrue(meta.containsKey("foobar"));
    assertEquals("bazbam", meta.get("foobar"));
    // competing update not overwritten
    assertEquals("collection1meta,collection2meta", zkStateReader.getAliases().getCollectionAliasMap().get("meta3"));
    // new properties added
    assertTrue(meta.containsKey("foo2"));
    assertEquals("bazbam", meta.get("foo2"));
    assertTrue(meta.containsKey("foo3"));
    assertEquals("bazbam2", meta.get("foo3"));
    // now check that an independently constructed ZkStateReader can see what we've done.
    // i.e. the data is really in zookeeper
    try (SolrZkClient zkClient = new SolrZkClient(cluster.getZkServer().getZkAddress(), 30000)) {
        ZkController.createClusterZkNodes(zkClient);
        try (ZkStateReader zkStateReader2 = new ZkStateReader(zkClient)) {
            zkStateReader2.createClusterStateWatchersAndUpdate();
            meta = zkStateReader2.getAliases().getCollectionAliasProperties("meta1");
            assertNotNull(meta);
            // verify key was removed in independent view
            assertFalse(meta.containsKey("foo"));
            // but only the specified key was removed
            assertTrue(meta.containsKey("foobar"));
            assertEquals("bazbam", meta.get("foobar"));
        }
    }
    // check removal leaves no props behind
    assertEquals(0, zkStateReader.getAliases().cloneWithCollectionAlias("meta1", // not persisted to zk on purpose
    null).getCollectionAliasProperties("meta1").size());
}

