@Test
public void testRestoreFailure() throws Exception {
    setTestSuffix("testfailure");
    replFactor = TestUtil.nextInt(random(), 1, 2);
    numTlogReplicas = TestUtil.nextInt(random(), 0, 1);
    numPullReplicas = TestUtil.nextInt(random(), 0, 1);
    CollectionAdminRequest.Create create = CollectionAdminRequest.createCollection(getCollectionName(), "conf1", NUM_SHARDS, replFactor, numTlogReplicas, numPullReplicas);
    if (NUM_SHARDS * (replFactor + numTlogReplicas + numPullReplicas) > cluster.getJettySolrRunners().size()) {
        //just to assert it survives the restoration
        create.setMaxShardsPerNode((int) Math.ceil(NUM_SHARDS * (replFactor + numTlogReplicas + numPullReplicas) / cluster.getJettySolrRunners().size()));
    }
    CloudSolrClient solrClient = cluster.getSolrClient();
    create.process(solrClient);
    indexDocs(getCollectionName(), false);
    String backupLocation = getBackupLocation();
    String backupName = BACKUPNAME_PREFIX + testSuffix;
    DocCollection backupCollection = solrClient.getZkStateReader().getClusterState().getCollection(getCollectionName());
    log.info("Triggering Backup command");
    {
        CollectionAdminRequest.Backup backup = CollectionAdminRequest.backupCollection(getCollectionName(), backupName).setLocation(backupLocation).setRepositoryName(getBackupRepoName());
        assertEquals(0, backup.process(solrClient).getStatus());
    }
    log.info("Triggering Restore command");
    String restoreCollectionName = getCollectionName() + "_restored";
    {
        CollectionAdminRequest.Restore restore = CollectionAdminRequest.restoreCollection(restoreCollectionName, backupName).setLocation(backupLocation).setRepositoryName(getBackupRepoName());
        if (backupCollection.getReplicas().size() > cluster.getJettySolrRunners().size()) {
            // may need to increase maxShardsPerNode (e.g. if it was shard split, then now we need more)
            restore.setMaxShardsPerNode((int) Math.ceil(backupCollection.getReplicas().size() / cluster.getJettySolrRunners().size()));
        }
        restore.setConfigName("confFaulty");
        assertEquals(RequestStatusState.FAILED, restore.processAndWait(solrClient, 30));
        assertThat("Failed collection is still in the clusterstate: " + cluster.getSolrClient().getClusterStateProvider().getClusterState().getCollectionOrNull(restoreCollectionName), CollectionAdminRequest.listCollections(solrClient), not(hasItem(restoreCollectionName)));
    }
}

