    String setTriggerCommand = "{" + "'set-trigger' : {" + "'name' : '" + AutoScaling.SCHEDULED_MAINTENANCE_TRIGGER_NAME + "'," + "'event' : 'scheduled'," + "'startTime' : 'NOW+10SECONDS'," + // must be longer than the cooldown period
    "'every' : '+2SECONDS'," + "'enabled' : true," + "'actions' : [{'name' : 'inactive_shard_plan', 'class' : 'solr.InactiveShardPlanAction', 'ttl' : '20'}," + "{'name' : 'execute_plan', 'class' : '" + ExecutePlanAction.class.getName() + "'}," + "{'name' : 'test', 'class' : '" + TestTriggerAction.class.getName() + "'}]" + "}}";
    req = AutoScalingRequest.create(SolrRequest.METHOD.POST, setTriggerCommand);
    response = solrClient.request(req);
    assertEquals(response.get("result").toString(), "success");
    boolean await = listenerCreated.await(10, TimeUnit.SECONDS);
