    // even when no external requests were made .. but it's hard to predict exactly
    // what it will be.  use an insanely high rate so all shards/nodes are suspect
    // and produce an Op regardless of how much internal traffic is produced...
    "'belowRate' : 1.0," + "'belowNodeRate' : 1.0," + // ...but do absolutely nothing to nodes except generate an 'NONE' Op
    "'belowNodeOp' : 'none'," + "'actions' : [" + "{'name':'compute','class':'" + ComputePlanAction.class.getName() + "'}," + "{'name':'execute','class':'" + ExecutePlanAction.class.getName() + "'}" + "]" + "}}");
