    assertTrue("the listener should have recorded all events w/in a reasonable amount of time", listenerEventLatch.await(60, TimeUnit.SECONDS));
    // suspend the trigger
    final String suspendTriggerCommand = "{ 'suspend-trigger' : { 'name' : 'search_rate_trigger2' } }";
    CloudTestUtils.assertAutoScalingRequest(cloudManager, suspendTriggerCommand);
    List<CapturedEvent> events = listenerEvents.get("srt");
