    assertEquals(ops.toString(), 2, ops.size());
    assertEquals(ops.toString(), CollectionParams.CollectionAction.NONE, ops.get(0).getAction());
    assertEquals(ops.toString(), CollectionParams.CollectionAction.NONE, ops.get(1).getAction());
    listenerEvents.clear();
    listenerEventLatch = new CountDownLatch(3);
    finished = new CountDownLatch(1);
    started = new CountDownLatch(1);
    log.info("## test single replicas.");
    // now allow single replicas
    CloudTestUtils.assertAutoScalingRequest(cloudManager, "{" + "'set-trigger' : {" + "'name' : 'search_rate_trigger2'," + "'event' : 'searchRate'," + "'waitFor' : '" + waitForSeconds + "s'," + "'enabled' : true," + "'collections' : '" + COLL1 + "'," + "'aboveRate' : 1.0," + "'aboveNodeRate' : 1.0," + // same excessively high values
    "'belowRate' : 1.0," + "'belowNodeRate' : 1.0," + // NEW: force lower replicas
    "'minReplicas' : 1," + // still do nothing to nodes
    "'belowNodeOp' : 'none'," + "'actions' : [" + "{'name':'compute','class':'" + ComputePlanAction.class.getName() + "'}," + "{'name':'execute','class':'" + ExecutePlanAction.class.getName() + "'}" + "]" + "}}");
    assertTrue("The trigger did not start in a reasonable amount of time", started.await(60, TimeUnit.SECONDS));
    assertTrue("The trigger did not finish in a reasonable amount of time", started.await(60, TimeUnit.SECONDS));
    assertTrue("the listener should have recorded all events w/in a reasonable amount of time", listenerEventLatch.await(60, TimeUnit.SECONDS));
