            }
            return true;
        });
        int counter = 0;
        do {
            trigger.run();
            timeSource.sleep(1000);
            if (counter++ > 10) {
                fail("Newly added node was not discovered by trigger even after 10 seconds");
            }
        } while (!fired.get());
