    assertTrue("cluster onChange listener didn't execute even after await()ing an excessive amount of time", listener.onChangeLatch.await(60, TimeUnit.SECONDS));
    assertEquals(1, listener.lostNodes.size());
    assertEquals(overseerLeader, listener.lostNodes.iterator().next());
    assertEquals(0, listener.addedNodes.size());
