    assertAutoScalingRequest("{" + "'set-trigger' : {" + "'name' : 'node_added_triggerMR'," + "'event' : 'nodeAdded'," + "'waitFor' : '1s'," + "'enabled' : true," + "'actions' : [{'name':'test','class':'" + TestEventMarkerAction.class.getName() + "'}]" + "}}");
