@Test
public void testBasic() throws Exception {
    // test using ZooKeeper
    assertTrue("Not using ZooKeeper", h.getCoreContainer().isZooKeeperAware());
    // for the really slow/busy computer, we wait to make sure we have a leader before starting
    h.getCoreContainer().getZkController().getZkStateReader().getLeaderUrl("collection1", "shard1", 30000);
    ZkController zkController = h.getCoreContainer().getZkController();
    SolrCore core = h.getCore();
    // test that we got the expected config, not just hardcoded defaults
    assertNotNull(core.getRequestHandler("/mock"));
    lrf.args.put(CommonParams.VERSION, "2.2");
    assertQ("test query on empty index", request("qlkciyopsbgzyvkylsjhchghjrdf"), "//result[@numFound='0']");
    // test escaping of ";"
    assertU("deleting 42 for no reason at all", delI("42"));
    assertU("adding doc#42", adoc("id", "42", "val_s", "aa;bb"));
    assertU("does commit work?", commit());
    assertQ("backslash escaping semicolon", request("id:42 AND val_s:aa\\;bb"), "//*[@numFound='1']", "//str[@name='id'][.='42']");
    assertQ("quote escaping semicolon", request("id:42 AND val_s:\"aa;bb\""), "//*[@numFound='1']", "//str[@name='id'][.='42']");
    assertQ("no escaping semicolon", request("id:42 AND val_s:aa"), "//*[@numFound='0']");
    assertU(delI("42"));
    assertU(commit());
    assertQ(request("id:42"), "//*[@numFound='0']");
    // test overwrite default of true
    assertU(adoc("id", "42", "val_s", "AAA"));
    assertU(adoc("id", "42", "val_s", "BBB"));
    assertU(commit());
    assertQ(request("id:42"), "//*[@numFound='1']", "//str[.='BBB']");
    assertU(adoc("id", "42", "val_s", "CCC"));
    assertU(adoc("id", "42", "val_s", "DDD"));
    assertU(commit());
    assertQ(request("id:42"), "//*[@numFound='1']", "//str[.='DDD']");
    // test deletes
    String[] adds = new String[] { add(doc("id", "101"), "overwrite", "true"), add(doc("id", "101"), "overwrite", "true"), add(doc("id", "105"), "overwrite", "false"), add(doc("id", "102"), "overwrite", "true"), add(doc("id", "103"), "overwrite", "false"), add(doc("id", "101"), "overwrite", "true") };
    for (String a : adds) {
        assertU(a, a);
    }
    assertU(commit());
    int zkPort = zkServer.getPort();
    zkServer.shutdown();
    // document indexing shouldn't stop immediately after a ZK disconnect
    assertU(adoc("id", "201"));
    Thread.sleep(300);
    // try a reconnect from disconnect
    zkServer = new ZkTestServer(zkDir, zkPort);
    zkServer.run(false);
    Thread.sleep(300);
    // ensure zk still thinks node is up
    assertTrue(zkController.getClusterState().getLiveNodes().toString(), zkController.getClusterState().liveNodesContain(zkController.getNodeName()));
    // test maxint
    assertQ(request("q", "id:[100 TO 110]", "rows", "2147483647"), "//*[@numFound='4']");
    // test big limit
    assertQ(request("q", "id:[100 TO 111]", "rows", "1147483647"), "//*[@numFound='4']");
    assertQ(request("id:[100 TO 110]"), "//*[@numFound='4']");
    assertU(delI("102"));
    assertU(commit());
    assertQ(request("id:[100 TO 110]"), "//*[@numFound='3']");
    assertU(delI("105"));
    assertU(commit());
    assertQ(request("id:[100 TO 110]"), "//*[@numFound='2']");
    assertU(delQ("id:[100 TO 110]"));
    assertU(commit());
    assertQ(request("id:[100 TO 110]"), "//*[@numFound='0']");
    // SOLR-2651: test that reload still gets config files from zookeeper
    zkController.getZkClient().setData("/configs/conf1/solrconfig.xml", new byte[0], true);
    // we set the solrconfig to nothing, so this reload should fail
    SolrException e = expectThrows(SolrException.class, "The reloaded SolrCore did not pick up configs from zookeeper", () -> {
        ignoreException("solrconfig.xml");
        h.getCoreContainer().reload(h.getCore().getName());
    });
    resetExceptionIgnores();
    assertTrue(e.getMessage().contains("Unable to reload core [collection1]"));
    assertTrue(e.getCause().getMessage().contains("Error loading solr config from solrconfig.xml"));
    // test stats call
    Map<String, Metric> metrics = h.getCore().getCoreMetricManager().getRegistry().getMetrics();
    assertEquals("collection1", ((Gauge) metrics.get("CORE.coreName")).getValue());
    assertEquals("collection1", ((Gauge) metrics.get("CORE.collection")).getValue());
    assertEquals("shard1", ((Gauge) metrics.get("CORE.shard")).getValue());
    assertTrue(metrics.get("CORE.refCount") != null);
    //zkController.getZkClient().printLayoutToStdOut();
}

@Test
@AwaitsFix(bugUrl = "https://issues.apache.org/jira/browse/SOLR-12524")
public void testBiDir() throws Exception {
    MiniSolrCloudCluster cluster2 = new MiniSolrCloudCluster(1, createTempDir("cdcr-cluster2"), buildJettyConfig("/solr"));
    MiniSolrCloudCluster cluster1 = new MiniSolrCloudCluster(1, createTempDir("cdcr-cluster1"), buildJettyConfig("/solr"));
    try {
        log.info("cluster2 zkHost = " + cluster2.getZkServer().getZkAddress());
        System.setProperty("cdcr.cluster2.zkHost", cluster2.getZkServer().getZkAddress());
        log.info("cluster1 zkHost = " + cluster1.getZkServer().getZkAddress());
        System.setProperty("cdcr.cluster1.zkHost", cluster1.getZkServer().getZkAddress());
        cluster1.uploadConfigSet(configset("cdcr-cluster1"), "cdcr-cluster1");
        CollectionAdminRequest.createCollection("cdcr-cluster1", "cdcr-cluster1", 2, 1).withProperty("solr.directoryFactory", "solr.StandardDirectoryFactory").setMaxShardsPerNode(2).process(cluster1.getSolrClient());
        CloudSolrClient cluster1SolrClient = cluster1.getSolrClient();
        cluster1SolrClient.setDefaultCollection("cdcr-cluster1");
        cluster2.uploadConfigSet(configset("cdcr-cluster2"), "cdcr-cluster2");
        CollectionAdminRequest.createCollection("cdcr-cluster2", "cdcr-cluster2", 2, 1).withProperty("solr.directoryFactory", "solr.StandardDirectoryFactory").setMaxShardsPerNode(2).process(cluster2.getSolrClient());
        CloudSolrClient cluster2SolrClient = cluster2.getSolrClient();
        cluster2SolrClient.setDefaultCollection("cdcr-cluster2");
        UpdateRequest req = null;
        CdcrTestsUtil.cdcrStart(cluster1SolrClient);
        Thread.sleep(2000);
        // ADD operation on cluster 1
        int docs = (TEST_NIGHTLY ? 100 : 10);
        int numDocs_c1 = 0;
        for (int k = 0; k < docs; k++) {
            req = new UpdateRequest();
            for (; numDocs_c1 < (k + 1) * 100; numDocs_c1++) {
                SolrInputDocument doc = new SolrInputDocument();
                doc.addField("id", "cluster1_" + numDocs_c1);
                doc.addField("xyz", numDocs_c1);
                req.add(doc);
            }
            req.setAction(AbstractUpdateRequest.ACTION.COMMIT, true, true);
            log.info("Adding " + docs + " docs with commit=true, numDocs=" + numDocs_c1);
            req.process(cluster1SolrClient);
        }
        QueryResponse response = cluster1SolrClient.query(new SolrQuery("*:*"));
        assertEquals("cluster 1 docs mismatch", numDocs_c1, response.getResults().getNumFound());
        assertEquals("cluster 2 docs mismatch", numDocs_c1, CdcrTestsUtil.waitForClusterToSync(numDocs_c1, cluster2SolrClient));
        // FULL BI-DIRECTIONAL CDCR FORWARDING ON
        CdcrTestsUtil.cdcrStart(cluster2SolrClient);
        Thread.sleep(2000);
        // ADD operation on cluster 2
        int numDocs_c2 = 0;
        for (int k = 0; k < docs; k++) {
            req = new UpdateRequest();
            for (; numDocs_c2 < (k + 1) * 100; numDocs_c2++) {
                SolrInputDocument doc = new SolrInputDocument();
                doc.addField("id", "cluster2_" + numDocs_c2);
                doc.addField("xyz", numDocs_c2);
                req.add(doc);
            }
            req.setAction(AbstractUpdateRequest.ACTION.COMMIT, true, true);
            log.info("Adding " + docs + " docs with commit=true, numDocs=" + numDocs_c2);
            req.process(cluster2SolrClient);
        }
        int numDocs = numDocs_c1 + numDocs_c2;
        response = cluster2SolrClient.query(new SolrQuery("*:*"));
        assertEquals("cluster 2 docs mismatch", numDocs, response.getResults().getNumFound());
        assertEquals("cluster 1 docs mismatch", numDocs, CdcrTestsUtil.waitForClusterToSync(numDocs, cluster1SolrClient));
        // logging cdcr clusters queue response
        response = CdcrTestsUtil.getCdcrQueue(cluster1SolrClient);
        log.info("Cdcr cluster1 queue response: " + response.getResponse());
        response = CdcrTestsUtil.getCdcrQueue(cluster2SolrClient);
        log.info("Cdcr cluster2 queue response: " + response.getResponse());
        // lets find and keep the maximum version assigned by cluster1 & cluster2 across all our updates
        long maxVersion_c1 = Math.min((long) CdcrTestsUtil.getFingerPrintMaxVersion(cluster1SolrClient, "shard1", numDocs), (long) CdcrTestsUtil.getFingerPrintMaxVersion(cluster1SolrClient, "shard2", numDocs));
        long maxVersion_c2 = Math.min((long) CdcrTestsUtil.getFingerPrintMaxVersion(cluster2SolrClient, "shard1", numDocs), (long) CdcrTestsUtil.getFingerPrintMaxVersion(cluster2SolrClient, "shard2", numDocs));
        ModifiableSolrParams params = new ModifiableSolrParams();
        params.set(CommonParams.ACTION, CdcrParams.CdcrAction.COLLECTIONCHECKPOINT.toString());
        params.set(CommonParams.QT, "/cdcr");
        response = cluster2SolrClient.query(params);
        Long checkpoint_2 = (Long) response.getResponse().get(CdcrParams.CHECKPOINT);
        assertNotNull(checkpoint_2);
        params = new ModifiableSolrParams();
        params.set(CommonParams.ACTION, CdcrParams.CdcrAction.COLLECTIONCHECKPOINT.toString());
        params.set(CommonParams.QT, "/cdcr");
        response = cluster1SolrClient.query(params);
        Long checkpoint_1 = (Long) response.getResponse().get(CdcrParams.CHECKPOINT);
        assertNotNull(checkpoint_1);
        log.info("v1: " + maxVersion_c1 + "\t" + "v2: " + maxVersion_c2 + "\t" + "checkpoint1: " + checkpoint_1 + "\t" + "checkpoint2: " + checkpoint_2);
        assertEquals("COLLECTIONCHECKPOINT from cluster2 should have returned the maximum " + "version across all updates made to cluster1", maxVersion_c1, checkpoint_2.longValue());
        assertEquals("COLLECTIONCHECKPOINT from cluster1 should have returned the maximum " + "version across all updates made to cluster2", maxVersion_c2, checkpoint_1.longValue());
        assertEquals("max versions of updates in both clusters should be same", maxVersion_c1, maxVersion_c2);
        // DELETE BY QUERY
        String deleteByQuery = "id:cluster1_" + String.valueOf(random().nextInt(numDocs_c1));
        response = cluster1SolrClient.query(new SolrQuery(deleteByQuery));
        assertEquals("should match exactly one doc", 1, response.getResults().getNumFound());
        cluster1SolrClient.deleteByQuery(deleteByQuery);
        cluster1SolrClient.commit();
        numDocs--;
        numDocs_c1--;
        response = cluster1SolrClient.query(new SolrQuery("*:*"));
        assertEquals("cluster 1 docs mismatch", numDocs, response.getResults().getNumFound());
        assertEquals("cluster 2 docs mismatch", numDocs, CdcrTestsUtil.waitForClusterToSync(numDocs, cluster2SolrClient));
        // DELETE BY ID
        SolrInputDocument doc;
        String delete_id_query = "cluster2_" + random().nextInt(numDocs_c2);
        cluster2SolrClient.deleteById(delete_id_query);
        cluster2SolrClient.commit();
        numDocs--;
        numDocs_c2--;
        response = cluster2SolrClient.query(new SolrQuery("*:*"));
        assertEquals("cluster 2 docs mismatch", numDocs, response.getResults().getNumFound());
        assertEquals("cluster 1 docs mismatch", numDocs, CdcrTestsUtil.waitForClusterToSync(numDocs, cluster1SolrClient));
        // ATOMIC UPDATES
        req = new UpdateRequest();
        doc = new SolrInputDocument();
        String atomicFieldName = "abc";
        String atomicUpdateId = "cluster2_" + random().nextInt(numDocs_c2);
        doc.addField("id", atomicUpdateId);
        doc.addField("xyz", ImmutableMap.of("delete", ""));
        doc.addField(atomicFieldName, ImmutableMap.of("set", "ABC"));
        req.add(doc);
        req.process(cluster2SolrClient);
        cluster2SolrClient.commit();
        String atomicQuery = "id:" + atomicUpdateId;
        response = cluster2SolrClient.query(new SolrQuery(atomicQuery));
        assertEquals("cluster 2 wrong doc", "ABC", response.getResults().get(0).get(atomicFieldName));
        assertEquals("cluster 1 wrong doc", "ABC", getDocFieldValue(cluster1SolrClient, atomicQuery, "ABC", atomicFieldName));
        // logging cdcr clusters queue response
        response = CdcrTestsUtil.getCdcrQueue(cluster1SolrClient);
        log.info("Cdcr cluster1 queue response at end of testcase: " + response.getResponse());
        response = CdcrTestsUtil.getCdcrQueue(cluster2SolrClient);
        log.info("Cdcr cluster2 queue response at end of testcase: " + response.getResponse());
        CdcrTestsUtil.cdcrStop(cluster1SolrClient);
        CdcrTestsUtil.cdcrStop(cluster2SolrClient);
    } finally {
        if (cluster1 != null) {
            cluster1.shutdown();
        }
        if (cluster2 != null) {
            cluster2.shutdown();
        }
    }
}

/**
 * Starts a source cluster with no CDCR configuration, indexes enough documents such that
 * the at least one old tlog is closed and thrown away so that the source cluster does not have
 * all updates available in tlogs only.
 * <p>
 * Then we start a target cluster with CDCR configuration and we change the source cluster configuration
 * to use CDCR (i.e. CdcrUpdateLog, CdcrRequestHandler and CdcrUpdateProcessor) and restart it.
 * <p>
 * We test that all updates eventually make it to the target cluster and that the collectioncheckpoint
 * call returns the same version as the last update indexed on the source.
 */
@Test
public // commented out on: 17-Feb-2019   @BadApple(bugUrl="https://issues.apache.org/jira/browse/SOLR-12028") // 14-Oct-2018
void testConvertClusterToCdcrAndBootstrap() throws Exception {
    // start the target first so that we know its zkhost
    MiniSolrCloudCluster target = new MiniSolrCloudCluster(1, createTempDir("cdcr-target"), buildJettyConfig("/solr"));
    try {
        log.info("Target zkHost = " + target.getZkServer().getZkAddress());
