@Test
@Repeat(iterations = 5)
public void testCreepThenBite() throws Exception {
    int creep = 100;
    ModifiableSolrParams params = params("q", "{!cache=false}name:a*");
    SolrParams[] cases = new SolrParams[] { params("sort", "query($q,1) asc"), params("rows", "0", "facet", "true", "facet.method", "enum", "facet.field", "name"), params("rows", "0", "json.facet", "{ ids: { type: range, field : num, start : 1, end : 99, gap : 9 }}"), params("q", "*:*", "rows", "0", "json.facet", "{ ids: { type: field, field : num}}"), params("q", "*:*", "rows", "0", "json.facet", "{ ids: { type: field, field : name_dv}}"), params("q", "*:*", "rows", "0", "json.facet", "{ ids: { type: field, field : name_dvs}}") };
    // add more cases here
    params.add(cases[random().nextInt(cases.length)]);
    for (; ; creep *= 1.5) {
        final int boundary = creep;
        try (Trap catchClass = catchCount(boundary)) {
            params.set("boundary", boundary);
            QueryResponse rsp = client.query(COLLECTION, params);
            assertEquals("" + rsp, rsp.getStatus(), 0);
            assertNo500s("" + rsp);
            if (!isPartial(rsp)) {
                assertFalse(catchClass.hasCaught());
                break;
            }
            assertTrue(catchClass.hasCaught());
        } catch (AssertionError ae) {
            Trap.dumpLastStackTraces(log);
            throw ae;
        }
    }
    int numBites = atLeast(100);
    for (int bite = 0; bite < numBites; bite++) {
        int boundary = random().nextInt(creep);
        boolean omitHeader = random().nextBoolean();
        try (Trap catchCount = catchCount(boundary)) {
            params.set("omitHeader", "" + omitHeader);
            params.set("boundary", boundary);
            QueryResponse rsp = client.query(COLLECTION, params);
            assertEquals("" + rsp, rsp.getStatus(), 0);
            assertNo500s("" + rsp);
            // without responseHeader, whether the response is partial or not can't be known
            // omitHeader=true used in request to ensure that no NPE exceptions are thrown
            if (omitHeader) {
                continue;
            }
            assertEquals("" + creep + " ticks were successful; trying " + boundary + " yields " + rsp, catchCount.hasCaught(), isPartial(rsp));
        } catch (AssertionError ae) {
            Trap.dumpLastStackTraces(log);
            throw ae;
        }
    }
}

@Test
public void testStoreAndRead() throws Exception {
    Map<String, DocCollection> collectionStates = new HashMap<>();
    Set<String> liveNodes = new HashSet<>();
    liveNodes.add("node1");
    liveNodes.add("node2");
    Map<String, Slice> slices = new HashMap<>();
    Map<String, Replica> sliceToProps = new HashMap<>();
    Map<String, Object> props = new HashMap<>();
    props.put("prop1", "value");
    props.put("prop2", "value2");
    Replica replica = new Replica("node1", props, "collection1", "shard1");
    sliceToProps.put("node1", replica);
    Slice slice = new Slice("shard1", sliceToProps, null, "collection1");
    slices.put("shard1", slice);
    Slice slice2 = new Slice("shard2", sliceToProps, null, "collection1");
    slices.put("shard2", slice2);
    collectionStates.put("collection1", new DocCollection("collection1", slices, null, DocRouter.DEFAULT));
    collectionStates.put("collection2", new DocCollection("collection2", slices, null, DocRouter.DEFAULT));
    ClusterState clusterState = new ClusterState(-1, liveNodes, collectionStates);
    byte[] bytes = Utils.toJSON(clusterState);
    // System.out.println("#################### " + new String(bytes));
    ClusterState loadedClusterState = ClusterState.load(-1, bytes, liveNodes);
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("No collections found", 2, loadedClusterState.getCollectionsMap().size());
    assertEquals("Properties not copied properly", replica.getStr("prop1"), loadedClusterState.getCollection("collection1").getSlice("shard1").getReplicasMap().get("node1").getStr("prop1"));
    assertEquals("Properties not copied properly", replica.getStr("prop2"), loadedClusterState.getCollection("collection1").getSlice("shard1").getReplicasMap().get("node1").getStr("prop2"));
    loadedClusterState = ClusterState.load(-1, new byte[0], liveNodes);
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("Should not have collections", 0, loadedClusterState.getCollectionsMap().size());
    loadedClusterState = ClusterState.load(-1, (byte[]) null, liveNodes);
    assertEquals("Provided liveNodes not used properly", 2, loadedClusterState.getLiveNodes().size());
    assertEquals("Should not have collections", 0, loadedClusterState.getCollectionsMap().size());
}

