@Test
public void testOverseerFailure() throws Exception {
    SolrZkClient overseerClient = null;
    ZkStateReader reader = null;
    MockZKController mockController = null;
    try {
        final String core = "core1";
        final String core_node = "core_node1";
        final String shard = "shard1";
        final int numShards = 1;
        ZkController.createClusterZkNodes(zkClient);
        reader = new ZkStateReader(zkClient);
        reader.createClusterStateWatchersAndUpdate();
        mockController = new MockZKController(server.getZkAddress(), "node1", overseers);
        overseerClient = electNewOverseer(server.getZkAddress());
        mockController.createCollection(COLLECTION, 1);
        ZkController zkController = createMockZkController(server.getZkAddress(), zkClient, reader);
        mockController.publishState(COLLECTION, core, core_node, "shard1", Replica.State.RECOVERING, numShards, true, overseers.get(0));
        waitForCollections(reader, COLLECTION);
        verifyReplicaStatus(reader, COLLECTION, "shard1", "core_node1", Replica.State.RECOVERING);
        mockController.publishState(COLLECTION, core, core_node, "shard1", Replica.State.ACTIVE, numShards, true, overseers.get(0));
        verifyReplicaStatus(reader, COLLECTION, "shard1", "core_node1", Replica.State.ACTIVE);
        mockController.publishState(COLLECTION, core, core_node, "shard1", Replica.State.RECOVERING, numShards, true, overseers.get(0));
        overseerClient.close();
        overseerClient = electNewOverseer(server.getZkAddress());
        verifyReplicaStatus(reader, COLLECTION, "shard1", "core_node1", Replica.State.RECOVERING);
        assertEquals("Live nodes count does not match", 1, reader.getClusterState().getLiveNodes().size());
        assertEquals(shard + " replica count does not match", 1, reader.getClusterState().getCollection(COLLECTION).getSlice(shard).getReplicasMap().size());
        mockController.publishState(COLLECTION, core, core_node, "shard1", null, numShards, true, overseers.get(1));
        reader.waitForState(COLLECTION, 5000, TimeUnit.MILLISECONDS, (liveNodes, collectionState) -> collectionState != null && collectionState.getReplica(core_node) == null);
        reader.forceUpdateCollection(COLLECTION);
        // as of SOLR-5209 core removal does not cascade to remove the slice and collection
        assertTrue(COLLECTION + " should remain after removal of the last core", reader.getClusterState().hasCollection(COLLECTION));
        assertTrue(core_node + " should be gone after publishing the null state", null == reader.getClusterState().getCollection(COLLECTION).getReplica(core_node));
    } finally {
        close(mockController);
        close(overseerClient);
        close(reader);
    }
}

