        ZkController.createClusterZkNodes(zkClient);
        reader = new ZkStateReader(zkClient);
        reader.createClusterStateWatchersAndUpdate();
        // We did not create /collections -> this message will cause exception when Overseer try to flush the clusterstate
        ZkNodeProps badMessage = new ZkNodeProps(Overseer.QUEUE_OPERATION, CollectionParams.CollectionAction.CREATE.toLower(), "name", "collection1", ZkStateReader.REPLICATION_FACTOR, "1", ZkStateReader.NUM_SHARDS_PROP, "1", DocCollection.STATE_FORMAT, "2", "createNodeSet", "");
        ZkNodeProps goodMessage = new ZkNodeProps(Overseer.QUEUE_OPERATION, CollectionParams.CollectionAction.CREATE.toLower(), "name", "collection2", ZkStateReader.REPLICATION_FACTOR, "1", ZkStateReader.NUM_SHARDS_PROP, "1", DocCollection.STATE_FORMAT, "1", "createNodeSet", "");
        ZkDistributedQueue workQueue = Overseer.getInternalWorkQueue(zkClient, new Stats());
        workQueue.offer(Utils.toJSON(badMessage));
        workQueue.offer(Utils.toJSON(goodMessage));
        overseerClient = electNewOverseer(server.getZkAddress());
        waitForCollections(reader, "collection2");
        ZkDistributedQueue q = getOpenOverseer().getStateUpdateQueue();
        q.offer(Utils.toJSON(badMessage));
