@Test
public void testRemovalOfLastReplica() throws Exception {
    // between 1 and 4 replicas
    final Integer numReplicas = 1 + random().nextInt(4);
    // between 1 and 4 shards
    final Integer numShards = 1 + random().nextInt(4);
    ZkStateReader zkStateReader = null;
    SolrZkClient overseerClient = null;
    try {
        ZkController.createClusterZkNodes(zkClient);
        zkStateReader = new ZkStateReader(zkClient);
        zkStateReader.createClusterStateWatchersAndUpdate();
        overseerClient = electNewOverseer(server.getZkAddress());
        ZkDistributedQueue q = overseers.get(0).getStateUpdateQueue();
        // create collection
        {
            final Integer maxShardsPerNode = numReplicas * numShards;
            ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, CollectionParams.CollectionAction.CREATE.toLower(), "name", COLLECTION, ZkStateReader.NUM_SHARDS_PROP, numShards.toString(), ZkStateReader.REPLICATION_FACTOR, "1", ZkStateReader.MAX_SHARDS_PER_NODE, maxShardsPerNode.toString());
            q.offer(Utils.toJSON(m));
        }
        waitForCollections(zkStateReader, COLLECTION);
        // create nodes with state recovering
        for (int rr = 1; rr <= numReplicas; ++rr) {
            for (int ss = 1; ss <= numShards; ++ss) {
                final int N = (numReplicas - rr) * numShards + ss;
                ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.STATE.toLower(), ZkStateReader.BASE_URL_PROP, "http://127.0.0.1/solr", ZkStateReader.SHARD_ID_PROP, "shard" + ss, ZkStateReader.NODE_NAME_PROP, "node" + N, ZkStateReader.COLLECTION_PROP, COLLECTION, ZkStateReader.CORE_NAME_PROP, "core" + N, ZkStateReader.CORE_NODE_NAME_PROP, "core_node" + N, ZkStateReader.ROLES_PROP, "", ZkStateReader.STATE_PROP, Replica.State.RECOVERING.toString());
                q.offer(Utils.toJSON(m));
            }
        }
        // verify recovering
        for (int rr = 1; rr <= numReplicas; ++rr) {
            for (int ss = 1; ss <= numShards; ++ss) {
                final int N = (numReplicas - rr) * numShards + ss;
                verifyReplicaStatus(zkStateReader, COLLECTION, "shard" + ss, "core_node" + N, Replica.State.RECOVERING);
            }
        }
        // publish node states (active)
        for (int rr = 1; rr <= numReplicas; ++rr) {
            for (int ss = 1; ss <= numShards; ++ss) {
                final int N = (numReplicas - rr) * numShards + ss;
                ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.STATE.toLower(), ZkStateReader.BASE_URL_PROP, "http://127.0.0.1/solr", ZkStateReader.SHARD_ID_PROP, "shard" + ss, ZkStateReader.NODE_NAME_PROP, "node" + N, ZkStateReader.COLLECTION_PROP, COLLECTION, ZkStateReader.CORE_NAME_PROP, "core" + N, ZkStateReader.ROLES_PROP, "", ZkStateReader.STATE_PROP, Replica.State.ACTIVE.toString());
                q.offer(Utils.toJSON(m));
            }
        }
        // verify active
        for (int rr = 1; rr <= numReplicas; ++rr) {
            for (int ss = 1; ss <= numShards; ++ss) {
                final int N = (numReplicas - rr) * numShards + ss;
                verifyReplicaStatus(zkStateReader, COLLECTION, "shard" + ss, "core_node" + N, Replica.State.ACTIVE);
            }
        }
        // delete node
        for (int rr = 1; rr <= numReplicas; ++rr) {
            for (int ss = 1; ss <= numShards; ++ss) {
                final int N = (numReplicas - rr) * numShards + ss;
                ZkNodeProps m = new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.DELETECORE.toLower(), ZkStateReader.COLLECTION_PROP, COLLECTION, ZkStateReader.CORE_NODE_NAME_PROP, "core_node" + N);
                q.offer(Utils.toJSON(m));
                {
                    String shard = "shard" + ss;
                    zkStateReader.waitForState(COLLECTION, 15000, TimeUnit.MILLISECONDS, (liveNodes, collectionState) -> collectionState != null && (collectionState.getSlice(shard) == null || collectionState.getSlice(shard).getReplicasMap().get("core_node" + N) == null));
                }
                final DocCollection docCollection = zkStateReader.getClusterState().getCollection(COLLECTION);
                assertTrue("found no " + COLLECTION, (null != docCollection));
                final Slice slice = docCollection.getSlice("shard" + ss);
                assertTrue("found no " + COLLECTION + " shard" + ss + " slice after removal of replica " + rr + " of " + numReplicas, (null != slice));
                final Collection<Replica> replicas = slice.getReplicas();
                assertEquals("wrong number of " + COLLECTION + " shard" + ss + " replicas left, replicas=" + replicas, numReplicas - rr, replicas.size());
            }
        }
    } finally {
        close(overseerClient);
        close(zkStateReader);
    }
}

@Test
public void testLatchWatcher() throws InterruptedException {
    OverseerTaskQueue.LatchWatcher latch1 = new OverseerTaskQueue.LatchWatcher();
    long before = System.nanoTime();
    latch1.await(100);
    long after = System.nanoTime();
    assertTrue(TimeUnit.NANOSECONDS.toMillis(after - before) > 50);
    // Mostly to make sure the millis->nanos->millis is not broken
    assertTrue(TimeUnit.NANOSECONDS.toMillis(after - before) < 500);
    latch1.process(new WatchedEvent(new WatcherEvent(1, 1, "/foo/bar")));
    before = System.nanoTime();
    // Expecting no wait
    latch1.await(10000);
    after = System.nanoTime();
    assertTrue(TimeUnit.NANOSECONDS.toMillis(after - before) < 1000);
    final AtomicBoolean expectedEventProcessed = new AtomicBoolean(false);
    final AtomicBoolean doneWaiting = new AtomicBoolean(false);
    final OverseerTaskQueue.LatchWatcher latch2 = new OverseerTaskQueue.LatchWatcher(Event.EventType.NodeCreated);
    Thread t = new Thread(() -> {
        //Process an event of a different type first, this shouldn't release the latch
        latch2.process(new WatchedEvent(new WatcherEvent(Event.EventType.NodeDeleted.getIntValue(), 1, "/foo/bar")));
        assertFalse("Latch shouldn't have been released", doneWaiting.get());
        // Now process the correct type of event
        expectedEventProcessed.set(true);
        latch2.process(new WatchedEvent(new WatcherEvent(Event.EventType.NodeCreated.getIntValue(), 1, "/foo/bar")));
    });
    t.start();
    before = System.nanoTime();
    // It shouldn't wait this long, t should notify the lock
    latch2.await(10000);
    after = System.nanoTime();
    doneWaiting.set(true);
    assertTrue(expectedEventProcessed.get());
    assertTrue(TimeUnit.NANOSECONDS.toMillis(after - before) < 1000);
}

@Test
public void testPackageManager() throws Exception {
    PackageTool tool = new PackageTool();
    String solrUrl = cluster.getJettySolrRunner(0).getBaseUrl().toString();
    run(tool, new String[] { "-solrUrl", solrUrl, "list-installed" });
    run(tool, new String[] { "-solrUrl", solrUrl, "add-repo", "fullstory", "http://localhost:" + repositoryServer.getPort() });
    run(tool, new String[] { "-solrUrl", solrUrl, "list-available" });
    run(tool, new String[] { "-solrUrl", solrUrl, "install", "question-answer:1.0.0" });
    run(tool, new String[] { "-solrUrl", solrUrl, "list-installed" });
    CollectionAdminRequest.createCollection("abc", "conf1", 1, 1).process(cluster.getSolrClient());
    CollectionAdminRequest.createCollection("def", "conf2", 1, 1).process(cluster.getSolrClient());
    String rhPath = "/mypath2";
    run(tool, new String[] { "-solrUrl", solrUrl, "list-deployed", "question-answer" });
    run(tool, new String[] { "-solrUrl", solrUrl, "deploy", "question-answer", "-y", "-collections", "abc", "-p", "RH-HANDLER-PATH=" + rhPath });
    assertPackageVersion("abc", "question-answer", "1.0.0", rhPath, "1.0.0");
    run(tool, new String[] { "-solrUrl", solrUrl, "list-deployed", "question-answer" });
    run(tool, new String[] { "-solrUrl", solrUrl, "list-deployed", "-c", "abc" });
    // Should we test the "auto-update to latest" functionality or the default explicit deploy functionality
    boolean autoUpdateToLatest = random().nextBoolean();
    if (autoUpdateToLatest) {
        log.info("Testing auto-update to latest installed");
        // This command pegs the version to the latest available
        run(tool, new String[] { "-solrUrl", solrUrl, "deploy", "question-answer:latest", "-y", "-collections", "abc" });
        assertPackageVersion("abc", "question-answer", "$LATEST", rhPath, "1.0.0");
        run(tool, new String[] { "-solrUrl", solrUrl, "install", "question-answer" });
        assertPackageVersion("abc", "question-answer", "$LATEST", rhPath, "1.1.0");
    } else {
        log.info("Testing explicit deployment to a different/newer version");
        run(tool, new String[] { "-solrUrl", solrUrl, "install", "question-answer" });
        assertPackageVersion("abc", "question-answer", "1.0.0", rhPath, "1.0.0");
        if (random().nextBoolean()) {
            // even if parameters are not passed in, they should be picked up from previous deployment
            run(tool, new String[] { "-solrUrl", solrUrl, "deploy", "--update", "-y", "question-answer", "-collections", "abc", "-p", "RH-HANDLER-PATH=" + rhPath });
        } else {
            run(tool, new String[] { "-solrUrl", solrUrl, "deploy", "--update", "-y", "question-answer", "-collections", "abc" });
        }
        assertPackageVersion("abc", "question-answer", "1.1.0", rhPath, "1.1.0");
    }
    log.info("Running undeploy...");
    run(tool, new String[] { "-solrUrl", solrUrl, "undeploy", "question-answer", "-collections", "abc" });
    run(tool, new String[] { "-solrUrl", solrUrl, "list-deployed", "question-answer" });
}

