    baseUrl = baseUrl.substring(0, baseUrl.length() - "collection1".length());
    // we only set the connect timeout, not so timeout
    try (HttpSolrClient baseClient = getHttpSolrClient(baseUrl, 30000)) {
        baseClient.request(request);
    }
