        client.add(doc);
        client.commit();
    }
    Path dataDir = null;
    try (HttpSolrClient client = getHttpSolrClient(runner.getBaseUrl().toString())) {
        CoreStatus status = CoreAdminRequest.getCoreStatus("corex", true, client);
