        } else {
            // custom component
            highlightComponentName = "customhighlight" + random().nextInt();
            cluster.getSolrClient().request(new ConfigRequest("{\n" + "  'add-searchcomponent': {\n" + "    'name': '" + highlightComponentName + "',\n" + "    'class': '" + customHighlightComponentClassName() + "'\n" + "  }\n" + "}"), COLLECTION);
        }
        // handler
        cluster.getSolrClient().request(new ConfigRequest("{\n" + "  'add-requesthandler': {\n" + "    'name' : '" + customSearchHandlerName + "',\n" + "    'class' : 'org.apache.solr.handler.component.SearchHandler',\n" + "    'components' : [ '" + QueryComponent.COMPONENT_NAME + "', '" + highlightComponentName + "' ]\n" + "  }\n" + "}"), COLLECTION);
    }
