    //  7
    index(id, "12", "text", "d", "payload", ByteBuffer.wrap(new byte[] { 0x34, (byte) 0xdd, 0x4d }));
    // 12
    index(id, "13", "text", "d", "payload", ByteBuffer.wrap(new byte[] { (byte) 0x80, 0x11, 0x33 }));
