@Test
public void testReloadDuringBuild() throws Exception {
    ExecutorService executor = ExecutorUtil.newMDCAwareCachedThreadPool("InfixSuggesterTest");
    try {
        // Build the suggester in the background with a long dictionary
        Future job = executor.submit(() -> expectThrows(RuntimeException.class, SolrCoreState.CoreIsClosedException.class, () -> assertQ(req("qt", rh_analyzing_long, SuggesterParams.SUGGEST_BUILD_ALL, "true"), "//str[@name='command'][.='buildAll']")));
        h.reload();
        // Stop the dictionary's input iterator
        System.clearProperty(RandomTestDictionaryFactory.RandomTestDictionary.getEnabledSysProp("longRandomAnalyzingInfixSuggester"));
        job.get();
    } finally {
        ExecutorUtil.shutdownAndAwaitTermination(executor);
    }
}

@Test
public void testShutdownDuringBuild() throws Exception {
    ExecutorService executor = ExecutorUtil.newMDCAwareCachedThreadPool("InfixSuggesterTest");
    try {
        LinkedHashMap<Class<? extends Throwable>, List<Class<? extends Throwable>>> expected = new LinkedHashMap<>();
        expected.put(RuntimeException.class, Arrays.asList(SolrCoreState.CoreIsClosedException.class, SolrException.class, IllegalStateException.class, NullPointerException.class));
        final Throwable[] outerException = new Throwable[1];
        // Build the suggester in the background with a long dictionary
        Future job = executor.submit(() -> outerException[0] = expectThrowsAnyOf(expected, () -> assertQ(req("qt", rh_analyzing_long, SuggesterParams.SUGGEST_BUILD_ALL, "true"), "//str[@name='command'][.='buildAll']")));
        // TODO: is there a better way to ensure that the build has begun?
        Thread.sleep(100);
        h.close();
        // Stop the dictionary's input iterator
        System.clearProperty(RandomTestDictionaryFactory.RandomTestDictionary.getEnabledSysProp("longRandomAnalyzingInfixSuggester"));
        job.get();
        Throwable wrappedException = outerException[0].getCause();
        if (wrappedException instanceof SolrException) {
            String expectedMessage = "SolrCoreState already closed.";
            assertTrue("Expected wrapped SolrException message to contain '" + expectedMessage + "' but message is '" + wrappedException.getMessage() + "'", wrappedException.getMessage().contains(expectedMessage));
        } else if (wrappedException instanceof IllegalStateException && !(wrappedException instanceof SolrCoreState.CoreIsClosedException)) {
            // CoreIsClosedException extends IllegalStateException
            String expectedMessage = "Cannot commit on an closed writer. Add documents first";
            assertTrue("Expected wrapped IllegalStateException message to contain '" + expectedMessage + "' but message is '" + wrappedException.getMessage() + "'", wrappedException.getMessage().contains(expectedMessage));
        }
    } finally {
        ExecutorUtil.shutdownAndAwaitTermination(executor);
        // put the core back for other tests
        initCore("solrconfig-infixsuggesters.xml", "schema.xml");
    }
}

