            req.process(httpSolrClient);
            fail("An exception should be thrown when ZooKeeper is not connected and shards.tolerant=requireZkConnected");
        } catch (Exception e) {
            assertTrue("Unrecognized exception message: " + e, e.getMessage().contains("no servers hosting shard:") || e.getMessage().contains("ZooKeeper is not connected"));
        }
