@Test
public void testCSV() throws Exception {
    lrf.args.put(CommonParams.VERSION, "2.2");
    makeFile("id,str_s\n100,\"quoted\"\n101,\n102,\"\"\n103,");
    loadLocal("commit", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted']");
    assertQ(req("id:101"), "count(//str[@name='str_s'])=0");
    // 102 is a quoted zero length field ,"", as opposed to ,,
    // but we can't distinguish this case (and it's debateable
    // if we should).  Does CSV have a way to specify missing
    // from zero-length?
    assertQ(req("id:102"), "count(//str[@name='str_s'])=0");
    assertQ(req("id:103"), "count(//str[@name='str_s'])=0");
    // test overwrite by default
    loadLocal("commit", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    // test explicitly adding header=true (the default)
    loadLocal("commit", "true", "header", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    // test no overwrites
    loadLocal("commit", "true", "overwrite", "false");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='8']");
    // test overwrite
    loadLocal("commit", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    // test global value mapping
    loadLocal("commit", "true", "map", "quoted:QUOTED");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='QUOTED']");
    assertQ(req("id:101"), "count(//str[@name='str_s'])=0");
    assertQ(req("id:102"), "count(//str[@name='str_s'])=0");
    assertQ(req("id:103"), "count(//str[@name='str_s'])=0");
    // test value mapping to empty (remove)
    loadLocal("commit", "true", "map", "quoted:");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "count(//str[@name='str_s'])=0");
    // test value mapping from empty
    loadLocal("commit", "true", "map", ":EMPTY");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[.='EMPTY']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='EMPTY']");
    // test multiple map rules
    loadLocal("commit", "true", "map", ":EMPTY", "map", "quoted:QUOTED");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='QUOTED']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[.='EMPTY']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='EMPTY']");
    // test indexing empty fields
    loadLocal("commit", "true", "f.str_s.keepEmpty", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[.='']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[.='']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='']");
    // test overriding the name of fields
    loadLocal("commit", "true", "fieldnames", "id,my_s", "header", "true", "f.my_s.map", ":EMPTY");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='my_s']/str[.='quoted']");
    assertQ(req("id:101"), "count(//arr[@name='str_s']/str)=0");
    assertQ(req("id:102"), "count(//arr[@name='str_s']/str)=0");
    assertQ(req("id:103"), "count(//arr[@name='str_s']/str)=0");
    assertQ(req("id:101"), "//arr[@name='my_s']/str[.='EMPTY']");
    assertQ(req("id:102"), "//arr[@name='my_s']/str[.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='my_s']/str[.='EMPTY']");
    // test that header in file was skipped
    assertQ(req("id:id"), "//*[@numFound='0']");
    // test skipping a field via the "skip" parameter
    loadLocal("commit", "true", "keepEmpty", "true", "skip", "str_s");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:[100 TO 110]"), "count(//str[@name='str_s']/str)=0");
    // test skipping a field by specifying an empty name
    loadLocal("commit", "true", "keepEmpty", "true", "fieldnames", "id,");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:[100 TO 110]"), "count(//str[@name='str_s']/str)=0");
    // test loading file as if it didn't have a header
    loadLocal("commit", "true", "fieldnames", "id,my_s", "header", "false");
    assertQ(req("id:id"), "//*[@numFound='1']");
    assertQ(req("id:100"), "//arr[@name='my_s']/str[.='quoted']");
    // test skipLines
    loadLocal("commit", "true", "fieldnames", "id,my_s", "header", "false", "skipLines", "1");
    assertQ(req("id:id"), "//*[@numFound='1']");
    assertQ(req("id:100"), "//arr[@name='my_s']/str[.='quoted']");
    // test multi-valued fields via field splitting w/ mapping of subvalues
    makeFile("id,str_s\n" + "100,\"quoted\"\n" + "101,\"a,b,c\"\n" + "102,\"a,,b\"\n" + "103,\n");
    loadLocal("commit", "true", "f.str_s.map", ":EMPTY", "f.str_s.split", "true");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='4']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[1][.='a']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[2][.='b']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[3][.='c']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[2][.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='EMPTY']");
    // test alternate values for delimiters
    makeFile("id|str_s\n" + "100|^quoted^\n" + "101|a;'b';c\n" + "102|a;;b\n" + "103|\n" + // no backslash escaping should be done by default
    "104|a\\\\b\n");
    loadLocal("commit", "true", "separator", "|", "encapsulator", "^", "f.str_s.map", ":EMPTY", "f.str_s.split", "true", "f.str_s.separator", ";", "f.str_s.encapsulator", "'");
    assertQ(req("id:[100 TO 110]"), "//*[@numFound='5']");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[1][.='a']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[2][.='b']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[3][.='c']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[2][.='EMPTY']");
    assertQ(req("id:103"), "//arr[@name='str_s']/str[.='EMPTY']");
    assertQ(req("id:104"), "//arr[@name='str_s']/str[.='a\\\\b']");
    // test no escaping + double encapsulator escaping by default
    makeFile("id,str_s\n" + "100,\"quoted \"\" \\ string\"\n" + // double encap shouldn't be an escape outside encap
    "101,unquoted \"\" \\ string\n" + "102,end quote \\\n");
    loadLocal("commit", "true");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='quoted \" \\ string']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[.='unquoted \"\" \\ string']");
    assertQ(req("id:102"), "//arr[@name='str_s']/str[.='end quote \\']");
    // setting an escape should disable encapsulator
    makeFile("id,str_s\n" + // quotes should be part of value
    "100,\"quoted \"\" \\\" \\\\ string\"\n" + "101,unquoted \"\" \\\" \\, \\\\ string\n");
    loadLocal("commit", "true", "escape", "\\");
    assertQ(req("id:100"), "//arr[@name='str_s']/str[.='\"quoted \"\" \" \\ string\"']");
    assertQ(req("id:101"), "//arr[@name='str_s']/str[.='unquoted \"\" \" , \\ string']");
}

@Test
public void test() throws Exception {
    CloudSolrClient solrClient = cluster.getSolrClient();
    String collectionName = "HdfsBackupRestore";
    CollectionAdminRequest.Create create = CollectionAdminRequest.createCollection(collectionName, "conf1", 1, 1);
    create.process(solrClient);
    int nDocs = BackupRestoreUtils.indexDocs(solrClient, collectionName, docsSeed);
    DocCollection collectionState = solrClient.getZkStateReader().getClusterState().getCollection(collectionName);
    assertEquals(1, collectionState.getActiveSlices().size());
    Slice shard = collectionState.getActiveSlices().iterator().next();
    assertEquals(1, shard.getReplicas().size());
    Replica replica = shard.getReplicas().iterator().next();
    String replicaBaseUrl = replica.getStr(BASE_URL_PROP);
    String coreName = replica.getStr(ZkStateReader.CORE_NAME_PROP);
    String backupName = TestUtil.randomSimpleString(random(), 1, 5);
    boolean testViaReplicationHandler = random().nextBoolean();
    String baseUrl = cluster.getJettySolrRunners().get(0).getBaseUrl().toString();
    try (HttpSolrClient masterClient = getHttpSolrClient(replicaBaseUrl)) {
        // Create a backup.
        if (testViaReplicationHandler) {
            log.info("Running Backup via replication handler");
            BackupRestoreUtils.runReplicationHandlerCommand(baseUrl, coreName, ReplicationHandler.CMD_BACKUP, "hdfs", backupName);
            final BackupStatusChecker backupStatus = new BackupStatusChecker(masterClient, "/" + coreName + "/replication");
            backupStatus.waitForBackupSuccess(backupName, 30);
        } else {
            log.info("Running Backup via core admin api");
            Map<String, String> params = new HashMap<>();
            params.put("name", backupName);
            params.put(CoreAdminParams.BACKUP_REPOSITORY, "hdfs");
            BackupRestoreUtils.runCoreAdminCommand(replicaBaseUrl, coreName, CoreAdminAction.BACKUPCORE.toString(), params);
        }
        int numRestoreTests = nDocs > 0 ? TestUtil.nextInt(random(), 1, 5) : 1;
        for (int attempts = 0; attempts < numRestoreTests; attempts++) {
            //Modify existing index before we call restore.
            if (nDocs > 0) {
                //Delete a few docs
                int numDeletes = TestUtil.nextInt(random(), 1, nDocs);
                for (int i = 0; i < numDeletes; i++) {
                    masterClient.deleteByQuery(collectionName, "id:" + i);
                }
                masterClient.commit(collectionName);
                //Add a few more
                int moreAdds = TestUtil.nextInt(random(), 1, 100);
                for (int i = 0; i < moreAdds; i++) {
                    SolrInputDocument doc = new SolrInputDocument();
                    doc.addField("id", i + nDocs);
                    doc.addField("name", "name = " + (i + nDocs));
                    masterClient.add(collectionName, doc);
                }
                //Purposely not calling commit once in a while. There can be some docs which are not committed
                if (usually()) {
                    masterClient.commit(collectionName);
                }
            }
            // Snapshooter prefixes "snapshot." to the backup name.
            if (testViaReplicationHandler) {
                log.info("Running Restore via replication handler");
                // Snapshooter prefixes "snapshot." to the backup name.
                BackupRestoreUtils.runReplicationHandlerCommand(baseUrl, coreName, ReplicationHandler.CMD_RESTORE, "hdfs", backupName);
                while (!TestRestoreCore.fetchRestoreStatus(baseUrl, coreName)) {
                    Thread.sleep(1000);
                }
            } else {
                log.info("Running Restore via core admin api");
                Map<String, String> params = new HashMap<>();
                params.put("name", "snapshot." + backupName);
                params.put(CoreAdminParams.BACKUP_REPOSITORY, "hdfs");
                BackupRestoreUtils.runCoreAdminCommand(replicaBaseUrl, coreName, CoreAdminAction.RESTORECORE.toString(), params);
            }
            //See if restore was successful by checking if all the docs are present again
            BackupRestoreUtils.verifyDocs(nDocs, masterClient, coreName);
            // Verify the permissions for the backup folder.
            FileStatus status = fs.getFileStatus(new org.apache.hadoop.fs.Path("/backup/snapshot." + backupName));
            FsPermission perm = status.getPermission();
            assertEquals(FsAction.ALL, perm.getUserAction());
            assertEquals(FsAction.ALL, perm.getGroupAction());
            assertEquals(FsAction.ALL, perm.getOtherAction());
        }
    }
}

