            if (random().nextBoolean()) {
                // move the slave ahead
                for (int i = 0; i < 3; i++) {
                    index(slaveClient, "id", id++, "name", "name = " + i);
                }
                slaveClient.commit();
            }
        }
    } finally {
        if (useStraightStandardDirectory) {
            resetFactory();
        }
    }
}

