@Test
public void testPhraseHighlighter() {
    HashMap<String, String> args = new HashMap<>();
    args.put("hl", "true");
    args.put("hl.fl", "t_text");
    args.put("hl.fragsize", "40");
    args.put("hl.snippets", "10");
    args.put("hl.usePhraseHighlighter", "false");
    TestHarness.LocalRequestFactory sumLRF = h.getRequestFactory("", 0, 200, args);
    // String borrowed from Lucene's HighlighterTest
    String t = "This piece of text refers to Kennedy at the beginning then has a longer piece of text that is very long in the middle and finally ends with another reference to Kennedy";
    assertU(adoc("t_text", t, "id", "1"));
    assertU(commit());
    assertU(optimize());
    String oldHighlight1 = "//lst[@name='1']/arr[@name='t_text']/str[.='This piece of <em>text</em> <em>refers</em> to Kennedy']";
    String oldHighlight2 = "//lst[@name='1']/arr[@name='t_text']/str[.=' at the beginning then has a longer piece of <em>text</em>']";
    String oldHighlight3 = "//lst[@name='1']/arr[@name='t_text']/str[.=' with another <em>reference</em> to Kennedy']";
    String newHighlight1 = "//lst[@name='1']/arr[@name='t_text']/str[.='This piece of <em>text</em> <em>refers</em> to Kennedy']";
    // check if old functionality is still the same
    assertQ("Phrase highlighting - old", sumLRF.makeRequest("t_text:\"text refers\""), "//lst[@name='highlighting']/lst[@name='1']", oldHighlight1, oldHighlight2, oldHighlight3);
    assertQ("Phrase highlighting - old", sumLRF.makeRequest("t_text:text refers"), "//lst[@name='highlighting']/lst[@name='1']", oldHighlight1, oldHighlight2, oldHighlight3);
    // now check if Lucene-794 highlighting works as expected
    args.put("hl.usePhraseHighlighter", "true");
    sumLRF = h.getRequestFactory("", 0, 200, args);
    // check phrase highlighting
    assertQ("Phrase highlighting - Lucene-794", sumLRF.makeRequest("t_text:\"text refers\""), "//lst[@name='highlighting']/lst[@name='1']", newHighlight1);
    // non phrase queries should be highlighted as they were before this fix
    assertQ("Phrase highlighting - Lucene-794", sumLRF.makeRequest("t_text:text refers"), "//lst[@name='highlighting']/lst[@name='1']", oldHighlight1, oldHighlight2, oldHighlight3);
}

@Test
public void testGetHighlightFields() {
    HashMap<String, String> args = new HashMap<>();
    args.put("fl", "id score");
    args.put("hl", "true");
    args.put("hl.fl", "t*");
    assertU(// static stored
    adoc(// static stored
    "id", // static stored
    "0", // static stored
    "title", // static stored
    "test", // static not stored
    "text", // static not stored
    "test", // dynamic stored
    "foo_s", // dynamic stored
    "test", // dynamic not stored
    "foo_sI", // dynamic not stored
    "test", // dynamic stored
    "bar_s", // dynamic stored
    "test", // dynamic not stored
    "bar_sI", // dynamic not stored
    "test", "weight", // stored but not text
    "1.0"));
    assertU(commit());
    assertU(optimize());
    TestHarness.LocalRequestFactory lrf = h.getRequestFactory("", 0, 10, args);
    SolrQueryRequest request = lrf.makeRequest("test");
    SolrHighlighter highlighter = HighlightComponent.getHighlighter(h.getCore());
    List<String> highlightFieldNames = Arrays.asList(highlighter.getHighlightFields(null, request, new String[] {}));
    assertTrue("Expected to highlight on field \"title\"", highlightFieldNames.contains("title"));
    assertFalse("Expected to not highlight on field \"text\"", highlightFieldNames.contains("text"));
    assertFalse("Expected to not highlight on field \"weight\"", highlightFieldNames.contains("weight"));
    request.close();
    args.put("hl.fl", "foo_*");
    lrf = h.getRequestFactory("", 0, 10, args);
    request = lrf.makeRequest("test");
    highlighter = HighlightComponent.getHighlighter(h.getCore());
    highlightFieldNames = Arrays.asList(highlighter.getHighlightFields(null, request, new String[] {}));
    assertEquals("Expected one field to highlight on", 1, highlightFieldNames.size());
    assertEquals("Expected to highlight on field \"foo_s\"", "foo_s", highlightFieldNames.get(0));
    request.close();
    // SOLR-5127
    args.put("hl.fl", (random().nextBoolean() ? "foo_*,bar_*" : "bar_*,foo_*"));
    lrf = h.getRequestFactory("", 0, 10, args);
    // hl.fl ordering need not be preserved in output
    final Set<String> highlightedSetExpected = new HashSet<String>();
    highlightedSetExpected.add("foo_s");
    highlightedSetExpected.add("bar_s");
    try (LocalSolrQueryRequest localRequest = lrf.makeRequest("test")) {
        highlighter = HighlightComponent.getHighlighter(h.getCore());
        final Set<String> highlightedSetActual = new HashSet<String>(Arrays.asList(highlighter.getHighlightFields(null, localRequest, new String[] {})));
        assertEquals(highlightedSetExpected, highlightedSetActual);
    }
}

