public void testEqualsAndHash() throws Exception {
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test1", 4, 10L, 20L, true, true));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test2", 4, 10L, 20L, false, true));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test3", 4, 10L, 20L, true, false));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test4", 4, 10L, 20L, false, false));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test5", 4, 10L, null, true, true));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test6", 4, null, 20L, true, true));
    QueryUtils.checkHashEquals(LegacyNumericRangeQuery.newLongRange("test7", 4, null, null, true, true));
    QueryUtils.checkEqual(LegacyNumericRangeQuery.newLongRange("test8", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newLongRange("test8", 4, 10L, 20L, true, true));
    QueryUtils.checkUnequal(LegacyNumericRangeQuery.newLongRange("test9", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newLongRange("test9", 8, 10L, 20L, true, true));
    QueryUtils.checkUnequal(LegacyNumericRangeQuery.newLongRange("test10a", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newLongRange("test10b", 4, 10L, 20L, true, true));
    QueryUtils.checkUnequal(LegacyNumericRangeQuery.newLongRange("test11", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newLongRange("test11", 4, 20L, 10L, true, true));
    QueryUtils.checkUnequal(LegacyNumericRangeQuery.newLongRange("test12", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newLongRange("test12", 4, 10L, 20L, false, true));
    QueryUtils.checkUnequal(LegacyNumericRangeQuery.newLongRange("test13", 4, 10L, 20L, true, true), LegacyNumericRangeQuery.newFloatRange("test13", 4, 10f, 20f, true, true));
    // difference to int range is tested in TestNumericRangeQuery32
}

// Create several log watchers and ensure that new messages go to the new watcher.
// NOTE: Since the superclass logs messages, it's possible that there are one or more
//       messages in the queue at the start, especially with asynch logging.
//       All we really care about is that new watchers get the new messages, so test for that
//       explicitly. See SOLR-12732.
@Test
public void testLog4jWatcher() throws InterruptedException {
    LogWatcher watcher = null;
    int lim = random().nextInt(3) + 2;
    // Every time through this loop, insure that, of all the test messages that have been logged, only the current
    // test message is present. NOTE: there may be log messages from the superclass the first time around.
    List<String> oldMessages = new ArrayList<>(lim);
    for (int idx = 0; idx < lim; ++idx) {
        watcher = LogWatcher.newRegisteredLogWatcher(config, null);
        // Now log a message and ensure that the new watcher sees it.
        String msg = "This is a test message: " + idx;
        log.warn(msg);
        // Loop to give the logger time to process the async message and notify the new watcher.
        TimeOut timeOut = new TimeOut(10, TimeUnit.SECONDS, TimeSource.NANO_TIME);
        boolean foundNewMsg = false;
        boolean foundOldMessage = false;
        // In local testing this loop usually succeeds 1-2 tries, so it's not very expensive to loop.
        do {
            // Returns an empty (but non-null) list even if there are no messages yet.
            SolrDocumentList events = watcher.getHistory(-1, null);
            for (SolrDocument doc : events) {
                String oneMsg = (String) doc.get("message");
                if (oneMsg.equals(msg)) {
                    foundNewMsg = true;
                }
                // Check that no old messages bled over into this watcher.
                for (String oldMsg : oldMessages) {
                    if (oneMsg.equals(oldMsg)) {
                        foundOldMessage = true;
                    }
                }
            }
            if (foundNewMsg == false) {
                Thread.sleep(10);
            }
        } while (foundNewMsg == false && timeOut.hasTimedOut() == false);
        if (foundNewMsg == false || foundOldMessage) {
            System.out.println("Dumping all events in failed watcher:");
            SolrDocumentList events = watcher.getHistory(-1, null);
            for (SolrDocument doc : events) {
                System.out.println("   Event:'" + doc.toString() + "'");
            }
            System.out.println("Recorded old messages");
            for (String oldMsg : oldMessages) {
                System.out.println("    " + oldMsg);
            }
            fail("Did not find expected message state, dumped current watcher's messages above, last message added: '" + msg + "'");
        }
        oldMessages.add(msg);
    }
}

@Test
public void testOperatingSystemMetricSet() throws Exception {
    OperatingSystemMetricSet set = new OperatingSystemMetricSet();
    Map<String, Metric> metrics = set.getMetrics();
    assertTrue(metrics.size() > 0);
    for (String metric : NUMERIC_OS_METRICS) {
        Gauge<?> gauge = (Gauge<?>) metrics.get(metric);
        assertNotNull(metric, gauge);
        double value = ((Number) gauge.getValue()).doubleValue();
        // SystemLoadAverage on Windows may be -1.0
        assertTrue("unexpected value of " + metric + ": " + value, value >= 0 || value == -1.0);
    }
    for (String metric : STRING_OS_METRICS) {
        Gauge<?> gauge = (Gauge<?>) metrics.get(metric);
        assertNotNull(metric, gauge);
        String value = (String) gauge.getValue();
        assertNotNull(value);
        assertFalse(value.isEmpty());
    }
}

