public void testRandom() throws Exception {
    // All field values will be a number between 0 and cardinality
    int cardinality = 10000;
    // Fields to use for interval faceting
    String[] fields = new String[] { "test_s_dv", "test_i_dv", "test_l_dv", "test_f_dv", "test_d_dv", "test_dt_dv", "test_ss_dv", "test_is_dv", "test_fs_dv", "test_ls_dv", "test_ds_dv", "test_dts_dv", "test_s", "test_i", "test_l", "test_f", "test_d", "test_dt", "test_ss", "test_is", "test_fs", "test_ls", "test_ds", "test_dts", "test_i_p", "test_is_p", "test_l_p", "test_ls_p", "test_f_p", "test_fs_p", "test_d_p", "test_ds_p", "test_dts_p" };
    for (int i = 0; i < atLeast(500); i++) {
        if (random().nextInt(50) == 0) {
            //have some empty docs
