    assertQ("/select?q=" + newFieldName + ":mad", "/response/lst[@name='responseHeader']/int[@name='status'] = '0'", "/response/result[@name='response'][@numFound='0']");
    // should not match as the synonym mapping between "origin" and "synonym"
    // was not added before the document was indexed
    assertQ("/select?q=" + newFieldName + ":(" + URLEncoder.encode(multiTermSynonym, "UTF-8") + ")&sow=false", "/response/lst[@name='responseHeader']/int[@name='status'] = '0'", "/response/result[@name='response'][@numFound='0']");
    restTestHarness.reload();
    // now query for mad and we should see our test doc
    assertQ("/select?q=" + newFieldName + ":mad", "/response/lst[@name='responseHeader']/int[@name='status'] = '0'", "/response/result[@name='response'][@numFound='1']", "/response/result[@name='response']/doc/str[@name='id'][.='5150']");
    // now query for "synonym" and we should see our test doc with "origin"
    assertQ("/select?q=" + newFieldName + ":(" + URLEncoder.encode(multiTermSynonym, "UTF-8") + ")&sow=false", "/response/lst[@name='responseHeader']/int[@name='status'] = '0'", "/response/result[@name='response'][@numFound='1']", "/response/result[@name='response']/doc/str[@name='id'][.='040']");
    // test for SOLR-6015
    syns = new HashMap<>();
    syns.put("mb", Arrays.asList("megabyte"));
    assertJPut(endpoint, toJSONString(syns), "/responseHeader/status==0");
    syns.put("MB", Arrays.asList("MiB", "Megabyte"));
    assertJPut(endpoint, toJSONString(syns), "/responseHeader/status==0");
    assertJQ(endpoint + "/MB", "/MB==['Megabyte','MiB','megabyte']");
    // test for SOLR-6878 - by default, expand is true, but only applies when sending in a list
    List<String> m2mSyns = new ArrayList<>();
    m2mSyns.addAll(Arrays.asList("funny", "entertaining", "whimiscal", "jocular"));
    assertJPut(endpoint, toJSONString(m2mSyns), "/responseHeader/status==0");
    assertJQ(endpoint + "/funny", "/funny==['entertaining','funny','jocular','whimiscal']");
    assertJQ(endpoint + "/entertaining", "/entertaining==['entertaining','funny','jocular','whimiscal']");
    assertJQ(endpoint + "/jocular", "/jocular==['entertaining','funny','jocular','whimiscal']");
    assertJQ(endpoint + "/whimiscal", "/whimiscal==['entertaining','funny','jocular','whimiscal']");
}

