@Test
public void testCurrencyRangeSearch() throws Exception {
    assumeTrue("This test is only applicable to the XML file based exchange rate provider", expectedProviderClass.equals(FileExchangeRateProvider.class));
    clearIndex();
    // times 2
    final int emptyDocs = atLeast(50);
    final int negDocs = atLeast(5);
    // 0
    assertU(adoc("id", "0", fieldName, "0,USD"));
    // lots of docs w/o values
    for (int i = 100; i <= 100 + emptyDocs; i++) {
        assertU(adoc("id", "" + i));
    }
    // docs with values in ranges we'll query
    for (int i = 1; i <= 10; i++) {
        assertU(adoc("id", "" + i, fieldName, i + ",USD"));
    }
    // more docs w/o values
    for (int i = 500; i <= 500 + emptyDocs; i++) {
        assertU(adoc("id", "" + i));
    }
    // some negative values
    for (int i = -100; i > -100 - negDocs; i--) {
        assertU(adoc("id", "" + i, fieldName, i + ",USD"));
    }
    // 0
    assertU(adoc("id", "40", fieldName, "0,USD"));
    assertU(commit());
    assertQ(req("fl", "*,score", "q", fieldName + ":[2.00,USD TO 5.00,USD]"), "//*[@numFound='4']");
    assertQ(req("fl", "*,score", "q", fieldName + ":[0.50,USD TO 1.00,USD]"), "//*[@numFound='1']");
    assertQ(req("fl", "*,score", "q", fieldName + ":[24.00,USD TO 25.00,USD]"), "//*[@numFound='0']");
    // "GBP" currency code is 1/2 of a USD dollar, for testing.
    assertQ(req("fl", "*,score", "q", fieldName + ":[0.50,GBP TO 1.00,GBP]"), "//*[@numFound='2']");
    // "EUR" currency code is 2.5X of a USD dollar, for testing.
    assertQ(req("fl", "*,score", "q", fieldName + ":[24.00,EUR TO 25.00,EUR]"), "//*[@numFound='1']");
    // Slight asymmetric rate should work.
    assertQ(req("fl", "*,score", "q", fieldName + ":[24.99,EUR TO 25.01,EUR]"), "//*[@numFound='1']");
    // Open ended ranges without currency
    assertQ(req("fl", "*,score", "q", fieldName + ":[* TO *]"), "//*[@numFound='" + (2 + 10 + negDocs) + "']");
    // Open ended ranges without currency
    assertQ(req("fl", "*,score", "q", fieldName + ":*"), "//*[@numFound='" + (2 + 10 + negDocs) + "']");
    // Open ended ranges with currency
    assertQ(req("fl", "*,score", "q", fieldName + ":[*,EUR TO *,EUR]"), "//*[@numFound='" + (2 + 10 + negDocs) + "']");
    // Open ended start range without currency
    assertQ(req("fl", "*,score", "q", fieldName + ":[* TO 5,USD]"), "//*[@numFound='" + (2 + 5 + negDocs) + "']");
    // Open ended start range with currency (currency for the * won't matter)
    assertQ(req("fl", "*,score", "q", fieldName + ":[*,USD TO 5,USD]"), "//*[@numFound='" + (2 + 5 + negDocs) + "']");
    // Open ended end range
    assertQ(req("fl", "*,score", "q", fieldName + ":[3 TO *]"), "//*[@numFound='8']");
}

