    assertQ(req("q", "*:*", "facet", "true", "rows", "0", "facet.field", "datedv", "facet.sort", "index", "facet.offset", "33", "facet.limit", "1", "facet.mincount", "1"), "//lst[@name='datedv']/int[@name='1933-12-31T23:59:59.999Z'][.='1']");
