    // Even though offseting by 33, the sort order is abc1 abc11....abc2 so it throws the position in the return list off.
    assertQ(req("q", "*:*", "facet", "true", "rows", "0", "facet.field", "stringdv", "facet.sort", "index", "facet.offset", "33", "facet.limit", "1", "facet.mincount", "1"), "//lst[@name='stringdv']/int[@name='abc38'][.='1']");
    assertQ(req("q", "*:*", "facet", "true", "rows", "0", "facet.field", "booldv", "facet.sort", "count"), "//lst[@name='booldv']/int[@name='true'][.='83']", "//lst[@name='booldv']/int[@name='false'][.='33']");
