@Test
public void testDocValuesMatch() throws Exception {
    assertU(adoc("id", "1", "floatdv", "2", "intdv", "3", "doubledv", "3.1", "longdv", "5", "datedv", "1995-12-31T23:59:59.999Z", "stringdv", "b", "booldv", "false"));
    assertU(adoc("id", "2", "floatdv", "-5", "intdv", "4", "doubledv", "-4.3", "longdv", "2", "datedv", "1997-12-31T23:59:59.999Z", "stringdv", "a", "booldv", "true"));
    assertU(adoc("id", "3", "floatdv", "3", "intdv", "1", "doubledv", "2.1", "longdv", "1", "datedv", "1996-12-31T23:59:59.999Z", "stringdv", "c", "booldv", "false"));
    assertU(adoc("id", "4", "floatdv", "3", "intdv", "-1", "doubledv", "1.5", "longdv", "1", "datedv", "1996-12-31T23:59:59.999Z", "stringdv", "car"));
    assertU(commit());
    // string: termquery
    assertQ(req("q", "stringdv:car", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // string: range query
    assertQ(req("q", "stringdv:[b TO d]", "sort", "id_i asc"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]");
    // string: prefix query
    assertQ(req("q", "stringdv:c*", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=3]", "//result/doc[2]/str[@name='id'][.=4]");
    // string: wildcard query
    assertQ(req("q", "stringdv:c?r", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // string: regexp query
    assertQ(req("q", "stringdv:/c[a-b]r/", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // float: termquery
    assertQ(req("q", "floatdv:3", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=3]", "//result/doc[2]/str[@name='id'][.=4]");
    // float: rangequery
    assertQ(req("q", "floatdv:[2 TO 3]", "sort", "id_i asc"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]");
    // (neg) float: termquery
    assertQ(req("q", "floatdv:\"-5\"", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=2]");
    // (neg) float: rangequery
    assertQ(req("q", "floatdv:[-6 TO -4]", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=2]");
    // (cross zero bounds) float: rangequery
    assertQ(req("q", "floatdv:[-6 TO 2.1]", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]");
    // int: termquery
    assertQ(req("q", "intdv:1", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=3]");
    // int: rangequery
    assertQ(req("q", "intdv:[3 TO 4]", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]");
    // (neg) int: termquery
    assertQ(req("q", "intdv:\"-1\"", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=4]");
    // (neg) int: rangequery
    assertQ(req("q", "intdv:[-1 TO 1]", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=3]", "//result/doc[2]/str[@name='id'][.=4]");
    // long: termquery
    assertQ(req("q", "longdv:1", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=3]", "//result/doc[2]/str[@name='id'][.=4]");
    // long: rangequery
    assertQ(req("q", "longdv:[1 TO 2]", "sort", "id_i asc"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]");
    // double: termquery
    assertQ(req("q", "doubledv:3.1", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=1]");
    // double: rangequery
    assertQ(req("q", "doubledv:[2 TO 3.3]", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]");
    // (neg) double: termquery
    assertQ(req("q", "doubledv:\"-4.3\"", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=2]");
    // (neg) double: rangequery
    assertQ(req("q", "doubledv:[-6 TO -4]", "sort", "id_i asc"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=2]");
    // (cross zero bounds) double: rangequery
    assertQ(req("q", "doubledv:[-6 TO 2.0]", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=4]");
    // boolean basic queries:
    assertQ(req("q", "booldv:false", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]");
    assertQ(req("q", "booldv:true", "sort", "id_i asc"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=4]");
}

