    Number[] smallestPositive = new Number[] { Float.MIN_NORMAL, Double.MIN_NORMAL };
    Number[] positiveInfinity = new Number[] { Float.POSITIVE_INFINITY, Double.POSITIVE_INFINITY };
    Number[] negativeInfinity = new Number[] { Float.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY };
    Number[] largestValue = new Number[] { Float.MAX_VALUE, Double.MAX_VALUE };
    Number[] zero = new Number[] { 0f, 0d };
    Function<Supplier<Number>, Number> noNaN = (next) -> {
        Number num;
        while (String.valueOf(num = next.get()).equals("NaN")) ;
        return num;
    };
    List<Supplier<Number>> nextRandNoNaN = Arrays.asList(() -> noNaN.apply(() -> Float.intBitsToFloat(random().nextInt())), () -> noNaN.apply(() -> Double.longBitsToDouble(random().nextLong())));
    List<Function<Number, Long>> toSortableLong = Arrays.asList((num) -> (long) NumericUtils.floatToSortableInt(num.floatValue()), (num) -> NumericUtils.doubleToSortableLong(num.doubleValue()));
    // Number minusZero[] = new Number[] {-0f, -0d}; // -0 == 0, so we should not treat them differently (and we should not guarantee that sign is preserved... we should be able to index both as 0)
    for (int i = 0; i < fieldName.length; i++) {
        assertU(delQ("*:*"));
        commit();
        Number[] specialValues = new Number[] { largestNegative[i], smallestPositive[i], negativeInfinity[i], largestValue[i], positiveInfinity[i], zero[i] };
        List<Number> values = new ArrayList<>();
        int numDocs = 1 + random().nextInt(10);
        for (int j = 0; j < numDocs; j++) {
            if (random().nextInt(100) < 5) {
                // Add a boundary value with 5% probability
                values.add(specialValues[random().nextInt(specialValues.length)]);
            } else {
                if (fieldName[i].equals("floatdv")) {
                    // Add random values with 95% probability
                    values.add(Float.intBitsToFloat(random().nextInt()));
                } else {
                    values.add(Double.longBitsToDouble(random().nextLong()));
                }
            }
        }
        // Indexing
        for (int j = 0; j < values.size(); j++) {
            assertU(adoc("id", String.valueOf(j + 1), fieldName[i], String.valueOf(values.get(j))));
        }
        assertU(commit());
        log.info("Indexed values: " + values);
        // Querying
        int numQueries = 10000;
        for (int j = 0; j < numQueries; j++) {
            boolean minInclusive = random().nextBoolean();
            boolean maxInclusive = random().nextBoolean();
            Number minVal, maxVal;
            String min = String.valueOf(minVal = nextRandNoNaN.get(i).get());
            String max = String.valueOf(maxVal = nextRandNoNaN.get(i).get());
            // randomly use boundary values for min, 15% of the time
            int r = random().nextInt(100);
            if (r < 5) {
                minVal = negativeInfinity[i];
                min = "*";
            } else if (r < 10) {
                minVal = specialValues[random().nextInt(specialValues.length)];
                min = String.valueOf(minVal);
            } else if (r < 15) {
                minVal = values.get(random().nextInt(values.size()));
                min = String.valueOf(minVal);
            }
            // randomly use boundary values for max, 15% of the time
            r = random().nextInt(100);
            if (r < 5) {
                maxVal = positiveInfinity[i];
                max = "*";
            } else if (r < 10) {
                maxVal = specialValues[random().nextInt(specialValues.length)];
                max = String.valueOf(maxVal);
            } else if (r < 15) {
                // Don't pick a NaN for the range query
                Number tmp = values.get(random().nextInt(values.size()));
                if (!Double.isNaN(tmp.doubleValue()) && !Float.isNaN(tmp.floatValue())) {
                    maxVal = tmp;
                    max = String.valueOf(maxVal);
                }
            }
            List<String> tests = new ArrayList<>();
            int counter = 0;
            for (int k = 0; k < values.size(); k++) {
                Number val = values.get(k);
                long valSortable = toSortableLong.get(i).apply(val);
                long minSortable = toSortableLong.get(i).apply(minVal);
                long maxSortable = toSortableLong.get(i).apply(maxVal);
                if ((minInclusive && minSortable <= valSortable || !minInclusive && minSortable < valSortable || (min.equals("*") && val == negativeInfinity[i])) && (maxInclusive && maxSortable >= valSortable || !maxInclusive && maxSortable > valSortable || (max.equals("*") && val == positiveInfinity[i]))) {
                    counter++;
                    tests.add("//result/doc[" + counter + "]/str[@name='id'][.=" + (k + 1) + "]");
                    tests.add("//result/doc[" + counter + "]/float[@name='score'][.=1.0]");
                }
            }
            tests.add(0, "//*[@numFound='" + counter + "']");
            String[] testsArr = new String[tests.size()];
            for (int k = 0; k < tests.size(); k++) {
                testsArr[k] = tests.get(k);
            }
            log.info("Expected: " + tests);
            assertQ(req("q", fieldName[i] + ":" + (minInclusive ? '[' : '{') + min + " TO " + max + (maxInclusive ? ']' : '}'), "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), testsArr);
        }
    }
}

@Test
public void testFloatAndDoubleRangeQuery() throws Exception {
    String[] fieldName = new String[] { "floatdv", "doubledv" };
    String[] largestNegative = new String[] { String.valueOf(0f - Float.MIN_NORMAL), String.valueOf(0f - Double.MIN_NORMAL) };
    String[] negativeInfinity = new String[] { String.valueOf(Float.NEGATIVE_INFINITY), String.valueOf(Double.NEGATIVE_INFINITY) };
    String[] largestValue = new String[] { String.valueOf(Float.MAX_VALUE), String.valueOf(Double.MAX_VALUE) };
    for (int i = 0; i < fieldName.length; i++) {
        assertU(adoc("id", "1", fieldName[i], "2"));
        assertU(adoc("id", "2", fieldName[i], "-5"));
        assertU(adoc("id", "3", fieldName[i], "3"));
        assertU(adoc("id", "4", fieldName[i], "3"));
        assertU(adoc("id", "5", fieldName[i], largestNegative[i]));
        assertU(adoc("id", "6", fieldName[i], negativeInfinity[i]));
        assertU(adoc("id", "7", fieldName[i], largestValue[i]));
        assertU(commit());
        // Negative Zero to Positive
        assertQ(req("q", fieldName[i] + ":[-0.0 TO 2.5]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='1']", "//result/doc[1]/str[@name='id'][.=1]");
        // Negative to Positive Zero
        assertQ(req("q", fieldName[i] + ":[-6 TO 0]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=5]");
        // Negative to Positive
        assertQ(req("q", fieldName[i] + ":[-6 TO 2.5]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]", "//result/doc[3]/str[@name='id'][.=5]");
        // Positive to Positive
        assertQ(req("q", fieldName[i] + ":[2 TO 3]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]");
        // Positive to POSITIVE_INF
        assertQ(req("q", fieldName[i] + ":[2 TO *]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='4']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=3]", "//result/doc[3]/str[@name='id'][.=4]", "//result/doc[4]/str[@name='id'][.=7]");
        // NEGATIVE_INF to Negative
        assertQ(req("q", fieldName[i] + ":[* TO -1]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='2']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=6]");
        // NEGATIVE_INF to Positive
        assertQ(req("q", fieldName[i] + ":[* TO 2]", "sort", "id_i asc", "fl", "id," + fieldName[i]), "//*[@numFound='4']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]", "//result/doc[3]/str[@name='id'][.=5]", "//result/doc[4]/str[@name='id'][.=6]");
        // NEGATIVE_INF to Positive (non-inclusive)
        assertQ(req("q", fieldName[i] + ":[* TO 2}", "sort", "id_i asc", "fl", "id," + fieldName[i]), "//*[@numFound='3']", "//result/doc[1]/str[@name='id'][.=2]", "//result/doc[2]/str[@name='id'][.=5]", "//result/doc[3]/str[@name='id'][.=6]");
        // Negative to POSITIVE_INF
        assertQ(req("q", fieldName[i] + ":[-6 TO *]", "sort", "id_i asc", "fl", "id," + fieldName[i]), "//*[@numFound='6']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]", "//result/doc[3]/str[@name='id'][.=3]", "//result/doc[4]/str[@name='id'][.=4]", "//result/doc[5]/str[@name='id'][.=5]", "//result/doc[6]/str[@name='id'][.=7]");
        // NEGATIVE_INF to POSITIVE_INF
        assertQ(req("q", fieldName[i] + ":[* TO *]", "sort", "id_i asc", "fl", "id," + fieldName[i] + ",score"), "//*[@numFound='7']", "//result/doc[1]/str[@name='id'][.=1]", "//result/doc[2]/str[@name='id'][.=2]", "//result/doc[3]/str[@name='id'][.=3]", "//result/doc[4]/str[@name='id'][.=4]", "//result/doc[5]/str[@name='id'][.=5]", "//result/doc[6]/str[@name='id'][.=6]", "//result/doc[7]/str[@name='id'][.=7]", "//result/doc[1]/float[@name='score'][.=1.0]", "//result/doc[2]/float[@name='score'][.=1.0]", "//result/doc[3]/float[@name='score'][.=1.0]", "//result/doc[4]/float[@name='score'][.=1.0]", "//result/doc[5]/float[@name='score'][.=1.0]", "//result/doc[6]/float[@name='score'][.=1.0]", "//result/doc[7]/float[@name='score'][.=1.0]");
    }
}

