@Test
public void testMethodStream() throws Exception {
    Client client = Client.localClient();
    indexSimple(client);
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{x:'sum(num_is)'}"), "facets=={count:6 , x:,10.0}");
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{x:'min(num_is)'}"), "facets=={count:6 , x:,-9}");
    // test multiple json.facet commands
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{x:'sum(num_d)'}", "json.facet", "{y:'min(num_d)'}", "json.facet", "{z:'min(num_is)'}"), "facets=={count:6 , x:3.0, y:-9.0, z:-9 }");
    // test streaming
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", // won't stream; need sort:index asc
    "{   cat:{terms:{field:'cat_s', method:stream }}" + ", cat2:{terms:{field:'cat_s', method:stream, sort:'index asc' }}" + // mincount
    ", cat3:{terms:{field:'cat_s', method:stream, sort:'index asc', mincount:3 }}" + // prefix
    ", cat4:{terms:{field:'cat_s', method:stream, sort:'index asc', prefix:B }}" + // offset
    ", cat5:{terms:{field:'cat_s', method:stream, sort:'index asc', offset:1 }}" + " }"), "facets=={count:6 " + ", cat :{buckets:[{val:B, count:3},{val:A, count:2}]}" + ", cat2:{buckets:[{val:A, count:2},{val:B, count:3}]}" + ", cat3:{buckets:[{val:B, count:3}]}" + ", cat4:{buckets:[{val:B, count:3}]}" + ", cat5:{buckets:[{val:B, count:3}]}" + " }");
    // test nested streaming under non-streaming
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{   cat:{terms:{field:'cat_s', sort:'index asc', facet:{where:{terms:{field:where_s,method:stream,sort:'index asc'}}}   }}}"), "facets=={count:6 " + ", cat :{buckets:[{val:A, count:2, where:{buckets:[{val:NJ,count:1},{val:NY,count:1}]}   },{val:B, count:3, where:{buckets:[{val:NJ,count:2},{val:NY,count:1}]}    }]}" + "}");
    // test nested streaming under streaming
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{   cat:{terms:{field:'cat_s', method:stream,sort:'index asc', facet:{where:{terms:{field:where_s,method:stream,sort:'index asc'}}}   }}}"), "facets=={count:6 " + ", cat :{buckets:[{val:A, count:2, where:{buckets:[{val:NJ,count:1},{val:NY,count:1}]}   },{val:B, count:3, where:{buckets:[{val:NJ,count:2},{val:NY,count:1}]}    }]}" + "}");
    // test nested streaming with stats under streaming
    assertJQ(req("q", "*:*", "rows", "0", "json.facet", "{   cat:{terms:{field:'cat_s', method:stream,sort:'index asc', facet:{  where:{terms:{field:where_s,method:stream,sort:'index asc',sort:'index asc', facet:{x:'max(num_d)', y:'sum(num_is)'}     }}}   }}}"), "facets=={count:6 " + ", cat :{buckets:[{val:A, count:2, where:{buckets:[{val:NJ,count:1,x:2.0,y:5.0},{val:NY,count:1,x:4.0,y:6.0}]}   }," + "{val:B, count:3, where:{buckets:[{val:NJ,count:2,x:11.0,y:4.0},{val:NY,count:1,x:-5.0,y:-5.0}]}    }]}" + "}");
    // test nested streaming with stats under streaming with stats
    assertJQ(req("q", "*:*", "rows", "0", "facet", "true", "json.facet", "{   cat:{terms:{field:'cat_s', method:stream,sort:'index asc', facet:{ y:'min(num_d)',  where:{terms:{field:where_s,method:stream,sort:'index asc', facet:{x:'max(num_d)'}     }}}   }}}"), "facets=={count:6 " + ", cat :{buckets:[{val:A, count:2, y:2.0, where:{buckets:[{val:NJ,count:1,x:2.0},{val:NY,count:1,x:4.0}]}   },{val:B, count:3, y:-9.0, where:{buckets:[{val:NJ,count:2,x:11.0},{val:NY,count:1,x:-5.0}]}    }]}" + "}");
    assertJQ(req("q", "*:*", "fq", "cat_s:A"), "response/numFound==2");
