@Test
public void testRangeFacetsErrorCases() throws Exception {
    Client client = Client.localClient();
    client.deleteByQuery("*:*", null);
    indexSimple(client);
    SolrParams params = params("q", "*:*", "rows", "0");
    // invalid format for ranges
    SolrException ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i,start:-10,end:10,gap:2," + "ranges:[{key:\"0-200\", to:200}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("Cannot set gap/start/end and ranges params together", ex.getMessage());
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:bleh}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Expected List for ranges but got String"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[bleh]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Expected Map for range but got String"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{from:0, to:200, inclusive_to:bleh}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Expected boolean type for param 'inclusive_to' but got String"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{from:0, to:200, inclusive_from:bleh}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Expected boolean type for param 'inclusive_from' but got String"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{from:bleh, to:200}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("Can't parse value bleh for field: num_i", ex.getMessage());
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{from:0, to:bleh}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("Can't parse value bleh for field: num_i", ex.getMessage());
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{from:200, to:0}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("'from' is higher than 'to' in range for key: [200,0)", ex.getMessage());
    // with old format
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("empty facet range"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"bl\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Invalid start character b in facet range bl"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"(bl\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertTrue(ex.getMessage().contains("Invalid end character l in facet range (bl"));
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"(bleh,12)\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("Can't parse value bleh for field: num_i", ex.getMessage());
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"(12,bleh)\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("Can't parse value bleh for field: num_i", ex.getMessage());
    ex = expectThrows(SolrException.class, () -> h.query(req(params, "json.facet", "{price:{type :range, field : num_i," + "ranges:[{range:\"(200,12)\"}]}}")));
    assertEquals(SolrException.ErrorCode.BAD_REQUEST.code, ex.code());
    assertEquals("'start' is higher than 'end' in range for key: (200,12)", ex.getMessage());
}

@Test
public void testOtherErrorCases() throws Exception {
    Client client = Client.localClient();
    client.deleteByQuery("*:*", null);
    indexSimple(client);
    // test for sort
    assertQEx("Should fail as sort is of type list", "Expected string/map for 'sort', received ArrayList=[count desc]", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:[\"count desc\"]}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as facet is not of type map", "Expected Map for 'facet', received ArrayList=[{}]", req("q", "*:*", "rows", "0", "json.facet", "[{}]"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as queries is not of type map", "Expected Map for 'queries', received [{}]", req("q", "*:*", "rows", "0", "json.queries", "[{}]"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as queries are null in JSON", "Expected Map for 'queries', received null", req("json", "{query:\"*:*\", queries:null}"), SolrException.ErrorCode.BAD_REQUEST);
    // range facets
    assertQEx("Should fail as 'other' is of type Map", "Expected list of string or comma separated string values for 'other', " + "received LinkedHashMap={} , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12, gap:1, other:{}}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as 'include' is of type Map", "Expected list of string or comma separated string values for 'include', " + "received LinkedHashMap={} , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12, gap:1, include:{}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing start parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'start' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing end parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'end' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10}}"), SolrException.ErrorCode.BAD_REQUEST);
    // missing gap parameter
    assertQEx("Should Fail with missing field error", "Missing required parameter: 'gap' , path=facet/f", req("q", "*:*", "json.facet", "{f:{type:range, field:num_d, start:10, end:12}}"), SolrException.ErrorCode.BAD_REQUEST);
    // invalid value for facet field
    assertQEx("Should Fail as args is of type long", "Expected string/map for facet field, received Long=2 , path=facet/facet", req("q", "*:*", "rows", "0", "json.facet.facet.field", "2"), SolrException.ErrorCode.BAD_REQUEST);
    // invalid value for facet query
    assertQEx("Should Fail as args is of type long for query", "Expected string/map for facet query, received Long=2 , path=facet/facet", req("q", "*:*", "rows", "0", "json.facet.facet.query", "2"), SolrException.ErrorCode.BAD_REQUEST);
    // valid facet field
    assertQ("Should pass as this is valid query", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s}}"));
    // invalid perSeg
    assertQEx("Should fail as perSeg is not of type boolean", "Expected boolean type for param 'perSeg' but got Long = 2 , path=facet/cat_s", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,perSeg:2}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as sort is invalid", "Invalid sort option 'bleh' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as sort order is invalid", "Unknown Sort direction 'bleh'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:{count: bleh}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // test for prelim_sort
    assertQEx("Should fail as prelim_sort is invalid", "Invalid prelim_sort option 'bleh' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,prelim_sort:bleh}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQEx("Should fail as prelim_sort map is invalid", "Invalid prelim_sort option '{bleh=desc}' for field 'cat_s'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,prelim_sort:{bleh:desc}}}"), SolrException.ErrorCode.BAD_REQUEST);
    // with nested facet
    assertQEx("Should fail as prelim_sort is invalid", "Invalid sort option 'bleh' for field 'id'", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh,facet:" + "{bleh:\"unique(cat_s)\",id:{type:terms,field:id,sort:bleh}}}}"), SolrException.ErrorCode.BAD_REQUEST);
    assertQ("Should pass as sort is proper", req("q", "*:*", "rows", "0", "json.facet", "{cat_s:{type:terms,field:cat_s,sort:bleh,facet:" + "{bleh:\"unique(cat_s)\",id:{type:terms,field:id,sort:{bleh:desc},facet:{bleh:\"unique(id)\"}}}}}"));
}

/**
 * Example from http://yonik.com/solr-nested-objects/
 * The main query gives us a document list of reviews by author_s:yonik
 * If we want to facet on the book genre (cat_s field) then we need to
 * switch the domain from the children (type_s:reviews) to the parents (type_s:books).
 *
 * And we get a facet over the books which yonik reviewed
 *
 * Note that regardless of which direction we are mapping
 * (parents to children or children to parents),
 * we provide a query that defines the complete set of parents in the index.
 * In these examples, the parent filter is “type_s:book”.
 */
@Test
public void testFacetingOnParents() throws Exception {
    final Client client = Client.localClient();
    ModifiableSolrParams p = params("rows", "10");
    client.testJQ(params(p, "q", "author_s:yonik", "fl", "id", "fl", "comment_t", "json.facet", "{" + "  genres: {" + "    type:terms," + "    field:cat_s," + "    domain: { blockParent : \"type_s:book\" }" + "  }" + "}"), "response=={numFound:2,start:0,docs:[" + "      {id:book1_c1," + "        comment_t:\"A great start to what looks like an epic series!\"}," + "      {id:book2_c1," + "        comment_t:\"Ahead of its time... I wonder if it helped inspire The Matrix?\"}]}", "facets=={ count:2," + "genres:{buckets:[ {val:fantasy, count:1}," + "                  {val:sci-fi,  count:1}]}}");
}

/**
