public void testJoin() throws Exception {
    assertU(add(doc("id", "1", "name_s", "john", "title_s", "Director", "dept_ss", "Engineering")));
    assertU(add(doc("id", "2", "name_s", "mark", "title_s", "VP", "dept_ss", "Marketing")));
