    assertU(add(doc("id", "5", "name_s", "tina", "title_s", "VP", "dept_ss", "Engineering")));
    assertU(add(doc("id", "10", "dept_id_s", "Engineering", "text_t", "These guys develop stuff")));
    assertU(add(doc("id", "11", "dept_id_s", "Marketing", "text_t", "These guys make you look good")));
    assertU(add(doc("id", "12", "dept_id_s", "Sales", "text_t", "These guys sell stuff")));
    assertU(add(doc("id", "13", "dept_id_s", "Support", "text_t", "These guys help customers")));
    assertU(commit());
    // test debugging TODO no debug in JoinUtil
    //  assertJQ(req("q","{!join from=dept_ss to=dept_id_s"+whateverScore()+"}title_s:MTS", "fl","id", "debugQuery","true")
    //      ,"/debug/join/{!join from=dept_ss to=dept_id_s"+whateverScore()+"}title_s:MTS=={'_MATCH_':'fromSetSize,toSetSize', 'fromSetSize':2, 'toSetSize':3}"
    //  );
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s" + whateverScore() + "}title_s:MTS", "fl", "id"), "/response=={'numFound':3,'start':0,'docs':[{'id':'10'},{'id':'12'},{'id':'13'}]}");
    // empty from
    assertJQ(req("q", "{!join from=noexist_s to=dept_id_s" + whateverScore() + "}*:*", "fl", "id"), "/response=={'numFound':0,'start':0,'docs':[]}");
    // empty to
    assertJQ(req("q", "{!join from=dept_ss to=noexist_s" + whateverScore() + "}*:*", "fl", "id"), "/response=={'numFound':0,'start':0,'docs':[]}");
    // self join... return everyone with she same title as Dave
    assertJQ(req("q", "{!join from=title_s to=title_s" + whateverScore() + "}name_s:dave", "fl", "id"), "/response=={'numFound':2,'start':0,'docs':[{'id':'3'},{'id':'4'}]}");
    // find people that develop stuff
    assertJQ(req("q", "{!join from=dept_id_s to=dept_ss" + whateverScore() + "}text_t:develop", "fl", "id"), "/response=={'numFound':3,'start':0,'docs':[{'id':'1'},{'id':'4'},{'id':'5'}]}");
    // self join on multivalued text_t field
    assertJQ(req("q", "{!join from=title_s to=title_s" + whateverScore() + "}name_s:dave", "fl", "id"), "/response=={'numFound':2,'start':0,'docs':[{'id':'3'},{'id':'4'}]}");
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s" + whateverScore() + "}title_s:MTS", "fl", "id", "debugQuery", "true"), "/response=={'numFound':3,'start':0,'docs':[{'id':'10'},{'id':'12'},{'id':'13'}]}");
    // expected outcome for a sub query matching dave joined against departments
    final String davesDepartments = "/response=={'numFound':2,'start':0,'docs':[{'id':'10'},{'id':'13'}]}";
    // straight forward query
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s" + whateverScore() + "}name_s:dave", "fl", "id"), davesDepartments);
    // variable deref for sub-query parsing
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s v=$qq" + whateverScore() + "}", "qq", "{!dismax}dave", "qf", "name_s", "fl", "id", "debugQuery", "true"), davesDepartments);
    // variable deref for sub-query parsing w/localparams
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s v=$qq" + whateverScore() + "}", "qq", "{!dismax qf=name_s}dave", "fl", "id", "debugQuery", "true"), davesDepartments);
    // defType local param to control sub-query parsing
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s defType=dismax" + whateverScore() + "}dave", "qf", "name_s", "fl", "id", "debugQuery", "true"), davesDepartments);
    // find people that develop stuff - but limit via filter query to a name of "john"
    // this tests filters being pushed down to queries (SOLR-3062)
    assertJQ(req("q", "{!join from=dept_id_s to=dept_ss" + whateverScore() + "}text_t:develop", "fl", "id", "fq", "name_s:john"), "/response=={'numFound':1,'start':0,'docs':[{'id':'1'}]}");
    assertJQ(req("q", "{!join from=dept_ss to=dept_id_s" + whateverScore() + "}title_s:MTS", "fl", "id"), "/response=={'numFound':3,'start':0,'docs':[{'id':'10'},{'id':'12'},{'id':'13'}]}");
    // find people that develop stuff, even if it's requested as single value
    assertJQ(req("q", "{!join from=dept_id_s to=dept_ss" + whateverScore() + "}text_t:develop", "fl", "id"), "/response=={'numFound':3,'start':0,'docs':[{'id':'1'},{'id':'4'},{'id':'5'}]}");
}

@SuppressWarnings({ "rawtypes", "unchecked" })
@Test
public void testRandomJoin() throws Exception {
    int indexIter = 50 * RANDOM_MULTIPLIER;
    int queryIter = 50 * RANDOM_MULTIPLIER;
    // groups of fields that have any chance of matching... used to
    // increase test effectiveness by avoiding 0 resultsets much of the time.
    String[][] compat = new String[][] { { "small_s_dv", "small2_s_dv", "small2_ss_dv", "small3_ss_dv" }, { "small_i_dv", "small2_i_dv", "small2_is_dv", "small3_is_dv" } };
    while (--indexIter >= 0) {
        int indexSize = random().nextInt(20 * RANDOM_MULTIPLIER);
        List<FldType> types = new ArrayList<FldType>();
        types.add(new FldType("id", ONE_ONE, new SVal('A', 'Z', 4, 4)));
        /**
         * no numeric fields so far LUCENE-5868
         *      types.add(new FldType("score_f_dv",ONE_ONE, new FVal(1,100)));  // field used to score
         */
        types.add(new FldType("small_s_dv", ZERO_ONE, new SVal('a', (char) ('c' + indexSize / 3), 1, 1)));
        types.add(new FldType("small2_s_dv", ZERO_ONE, new SVal('a', (char) ('c' + indexSize / 3), 1, 1)));
        types.add(new FldType("small2_ss_dv", ZERO_TWO, new SVal('a', (char) ('c' + indexSize / 3), 1, 1)));
        types.add(new FldType("small3_ss_dv", new IRange(0, 25), new SVal('A', 'z', 1, 1)));
        /**
         * no numeric fields so far LUCENE-5868
         *      types.add(new FldType("small_i_dv",ZERO_ONE, new IRange(0,5+indexSize/3)));
         *      types.add(new FldType("small2_i_dv",ZERO_ONE, new IRange(0,5+indexSize/3)));
         *      types.add(new FldType("small2_is_dv",ZERO_TWO, new IRange(0,5+indexSize/3)));
         *      types.add(new FldType("small3_is_dv",new IRange(0,25), new IRange(0,100)));
         */
        clearIndex();
        Map<Comparable, Doc> model = indexDocs(types, null, indexSize);
        Map<String, Map<Comparable, Set<Comparable>>> pivots = new HashMap<String, Map<Comparable, Set<Comparable>>>();
        for (int qiter = 0; qiter < queryIter; qiter++) {
            String fromField;
            String toField;
            if (random().nextInt(100) < 5) {
                // pick random fields 5% of the time
                fromField = types.get(random().nextInt(types.size())).fname;
                // pick the same field 50% of the time we pick a random field (since other fields won't match anything)
                toField = (random().nextInt(100) < 50) ? fromField : types.get(random().nextInt(types.size())).fname;
            } else {
                // otherwise, pick compatible fields that have a chance of matching indexed tokens
                String[] group = compat[random().nextInt(compat.length)];
                fromField = group[random().nextInt(group.length)];
                toField = group[random().nextInt(group.length)];
            }
            Map<Comparable, Set<Comparable>> pivot = pivots.get(fromField + "/" + toField);
            if (pivot == null) {
                pivot = createJoinMap(model, fromField, toField);
                pivots.put(fromField + "/" + toField, pivot);
            }
            Collection<Doc> fromDocs = model.values();
            Set<Comparable> docs = join(fromDocs, pivot);
            List<Doc> docList = new ArrayList<Doc>(docs.size());
            for (Comparable id : docs) docList.add(model.get(id));
            Collections.sort(docList, createComparator("_docid_", true, false, false, false));
            List sortedDocs = new ArrayList();
            for (Doc doc : docList) {
                if (sortedDocs.size() >= 10)
                    break;
                sortedDocs.add(doc.toObject(h.getCore().getLatestSchema()));
            }
            Map<String, Object> resultSet = new LinkedHashMap<String, Object>();
            resultSet.put("numFound", docList.size());
            resultSet.put("start", 0);
            resultSet.put("docs", sortedDocs);
            // todo: use different join queries for better coverage
            SolrQueryRequest req = req("wt", "json", "indent", "true", "echoParams", "all", "q", "{!join from=" + fromField + " to=" + toField + " " + (random().nextBoolean() ? "fromIndex=collection1" : "") + " " + (random().nextBoolean() ? "TESTenforceSameCoreAsAnotherOne=true" : "") + " " + whateverScore() + "}*:*", "sort", "_docid_ asc");
            String strResponse = h.query(req);
            Object realResponse = Utils.fromJSONString(strResponse);
            String err = JSONTestUtil.matchObj("/response", realResponse, resultSet);
            if (err != null) {
                final String m = "JOIN MISMATCH: " + err + "\n\trequest=" + req + "\n\tresult=" + strResponse + "\n\texpected=" + toJSONString(resultSet);
                // + "\n\tmodel="+ JSONUtil.toJSON(model);
                log.error(m);
                {
                    SolrQueryRequest f = req("wt", "json", "indent", "true", "echoParams", "all", "q", "*:*", "facet", "true", "facet.field", fromField, "sort", "_docid_ asc", "rows", "0");
                    log.error("faceting on from field: " + h.query(f));
                }
                {
                    final Map<String, String> ps = ((MapSolrParams) req.getParams()).getMap();
                    final String q = ps.get("q");
                    ps.put("q", q.replaceAll("join score=none", "join"));
                    log.error("plain join: " + h.query(req));
                    ps.put("q", q);
                }
                {
                    // re-execute the request... good for putting a breakpoint here for debugging
                    final Map<String, String> ps = ((MapSolrParams) req.getParams()).getMap();
                    final String q = ps.get("q");
                    ps.put("q", q.replaceAll("\\}", " cache=false\\}"));
                    h.query(req);
                }
                fail(err);
            }
        }
    }
}

@Test
public void testXcjfRoutedCollection() throws Exception {
    setupIndexes(true);
    testXcjfQuery("{!xcjf collection=products from=product_id_i to=product_id_i}size_s:M", true);
    int i = 0;
    for (JettySolrRunner runner : cluster.getJettySolrRunners()) {
        i++;
        String url = runner.getBaseUrl().toString();
        System.setProperty("test.xcjf.solr.url." + i, url);
    }
    try {
        // now we need to re-upload our config , now that we know a valid solr url for the cluster.
        CloudSolrClient client = cluster.getSolrClient();
        ((ZkClientClusterStateProvider) client.getClusterStateProvider()).uploadConfig(configset("xcjf"), "xcjf");
        // reload the cores with the updated whitelisted solr url config.
        CollectionAdminRequest.Reload.reloadCollection("products").process(client);
        CollectionAdminRequest.Reload.reloadCollection("parts").process(client);
        Thread.sleep(10000);
        testXcjfQuery("{!xcjf collection=products from=product_id_i to=product_id_i}size_s:M", true);
        testXcjfQuery(String.format(Locale.ROOT, "{!xcjf solrUrl=\"%s\" collection=products from=product_id_i to=product_id_i}size_s:M", getSolrUrl()), true);
        testXcjfQuery("{!xcjf collection=products from=product_id_l to=product_id_l}size_s:M", true);
        testXcjfQuery(String.format(Locale.ROOT, "{!xcjf solrUrl=\"%s\" collection=products from=product_id_l to=product_id_l}size_s:M", getSolrUrl()), true);
        testXcjfQuery("{!xcjf collection=products from=product_id_s to=product_id_s}size_s:M", true);
        testXcjfQuery(String.format(Locale.ROOT, "{!xcjf solrUrl=\"%s\" collection=products from=product_id_s to=product_id_s}size_s:M", getSolrUrl()), true);
        testXcjfQuery(String.format(Locale.ROOT, "{!xcjf zkHost=\"%s\" collection=products from=product_id_s to=product_id_s}size_s:M", cluster.getSolrClient().getZkHost()), true);
        // Test the ability to set other parameters on xcjf and have them passed through
        assertResultCount("parts", "{!xcjf collection=products from=product_id_s to=product_id_s fq=product_id_s:1}size_s:M", 2, true);
        assertResultCount("parts", String.format(Locale.ROOT, "{!xcjf solrUrl=\"%s\" collection=products from=product_id_s to=product_id_s fq=product_id_s:1}size_s:M", getSolrUrl()), 2, true);
    } finally {
        for (JettySolrRunner runner : cluster.getJettySolrRunners()) {
            i++;
            System.getProperties().remove("test.xcjf.solr.url." + i);
        }
    }
}

@Test
public void testXcjfNonroutedCollection() throws Exception {
    setupIndexes(false);
    // This query will expect the collection to have been routed on product_id, so it should return
    // incomplete results.
    testXcjfQuery("{!xcjf collection=products from=product_id_s to=product_id_s}size_s:M", false);
    // Now if we set routed=false we should get a complete set of results.
    testXcjfQuery("{!xcjf collection=products from=product_id_s to=product_id_s routed=false}size_s:M", true);
    // The xcjf_nonrouted query parser doesn't assume that the collection was routed on product_id,
    // so we should get the full set of results.
    testXcjfQuery("{!xcjf_nonrouted collection=products from=product_id_s to=product_id_s}size_s:M", true);
    // But if we set routed=true, we are now assuming again that the collection was routed on product_id,
    // so we should get incomplete results.
    testXcjfQuery("{!xcjf_nonrouted collection=products from=product_id_s to=product_id_s routed=true}size_s:M", false);
}

