@Test
public void testUnorderedPhraseQuery() {
    assertU(adoc("text", "protein digest", "id", "1"));
    assertU(adoc("text", "digest protein", "id", "2"));
    assertU(adoc("name", "protein digest", "id", "3"));
    assertU(adoc("name", "digest protein", "id", "4"));
    assertU(commit());
    assertU(optimize());
    /**
     * ordered phrase query return only fist document
     */
    assertQ(req("q", "{!complexphrase} \"protein digest\""), "//result[@numFound='1']", "//doc[./str[@name='id']='1']");
    assertQ(req("q", "{!complexphrase} \"pro* di*\""), "//result[@numFound='1']", "//doc[./str[@name='id']='1']");
    assertQ(req("q", "{!complexphrase} name:\"protein digest\""), "//result[@numFound='1']", "//doc[./str[@name='id']='3']");
    assertQ(req("q", "{!complexphrase} name:\"pro* di*\""), "//result[@numFound='1']", "//doc[./str[@name='id']='3']");
    /**
     * unordered phrase query returns two documents.
     */
    assertQ(req("q", "{!complexphrase inOrder=false} \"digest protein\""), "//result[@numFound='2']", "//doc[./str[@name='id']='1']", "//doc[./str[@name='id']='2']");
    assertQ(req("q", "{!complexphrase inOrder=false} \"di* pro*\""), "//result[@numFound='2']", "//doc[./str[@name='id']='1']", "//doc[./str[@name='id']='2']");
    assertQ(req("q", "{!complexphrase inOrder=false} name:\"digest protein\""), "//result[@numFound='2']", "//doc[./str[@name='id']='3']", "//doc[./str[@name='id']='4']");
    assertQ(req("q", "{!complexphrase inOrder=false} name:\"di* pro*\""), "//result[@numFound='2']", "//doc[./str[@name='id']='3']", "//doc[./str[@name='id']='4']");
    /**
     * inOrder parameter can be defined with local params syntax.
     */
    assertQ(req("q", "{!complexphrase inOrder=false} \"di* pro*\""), "//result[@numFound='2']", "//doc[./str[@name='id']='1']", "//doc[./str[@name='id']='2']");
    assertQ(req("q", "{!complexphrase inOrder=true} \"di* pro*\""), "//result[@numFound='1']");
    /**
     * inOrder and df parameters can be defined with local params syntax.
     */
    assertQ(req("q", "{!complexphrase inOrder=false df=name} \"di* pro*\""), "//result[@numFound='2']", "//doc[./str[@name='id']='3']", "//doc[./str[@name='id']='4']");
}

