    params.add("partitionKeys", "a_s, a_i, a_l");
    params.add("rows", "50");
    params.add("wt", "xml");
    set2 = new HashSet();
    response = h.query(req(params));
    it = set.iterator();
    while (it.hasNext()) {
        String s = it.next();
        String results = h.validateXPath(response, "*[count(//str[@name='id'][.='" + s + "'])=1]");
        if (results == null) {
            set2.add(s);
        }
    }
    assert (set1.size() > 0);
    assert (set2.size() > 0);
    assert (set1.size() + set2.size() == set.size());
    assertNoOverLap(set1, set2);
}

