    try {
        assertQueryEquals(req, "{!simple qf=$myField}foo*", "{!simple qf=$myField}foo*", "{!prefix f=swap_foo_bar_in_prefix_query}foo", "{!lucene df=$myField v=foo*}", "{!lucene}swap_foo_bar_in_prefix_query:foo*");
