                b = scc.getOriginal();
            } else if (scc.getOriginal().equals(TOKEN_AYE_BEE)) {
                ab = scc.getOriginal();
            } else if (scc.getOriginal().equals(TOKEN_CEE)) {
                c = scc.getOriginal();
            }
            if (ab != null) {
                abCount++;
            } else {
                aCount++;
            }
        }
        assertTrue(c != null);
        assertTrue(ab != null || (a != null && b != null));
        assertTrue(ab == null || (a == null && b == null));
        assertTrue(dupChecker.add(rsp));
    }
    assertTrue(aCount == 2160);
    assertTrue(abCount == 180);
}

