@Test
public void testGroupAPI() throws Exception {
    createIndex();
    String filt = f + ":[* TO *]";
    assertQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f), "/response/lst[@name='grouped']/lst[@name='" + f + "']/arr[@name='groups']");
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id"), // exact match
    "/responseHeader/status==0", // partial match by skipping some elements
    "/responseHeader=={'_SKIP_':'QTime', 'status':0}", // partial match by only including some elements
    "/responseHeader=={'_MATCH_':'status', 'status':0}", "/grouped=={'" + f + "':{'matches':10,'groups':[\n" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,'docs':[{'id':'8'}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,'docs':[{'id':'3'}]}}," + "{'groupValue':2,'doclist':{'numFound':3,'start':0,'docs':[{'id':'4'}]}}," + "{'groupValue':5,'doclist':{'numFound':1,'start':0,'docs':[{'id':'1'}]}}," + "{'groupValue':4,'doclist':{'numFound':1,'start':0,'docs':[{'id':'2'}]}}" + "]}}");
