    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "fq", f + ":2"), "/grouped=={'" + f + "':{'matches':3,'groups':[" + "{'groupValue':2,'doclist':{'numFound':3,'start':0,'docs':[{'id':'4'}]}}" + "]}}");
    // test limiting the number of groups returned
