@Test
public void testLogReaderNext() throws Exception {
    this.clearCore();
    int start = 0;
    UpdateLog ulog = h.getCore().getUpdateHandler().getUpdateLog();
    // test reader on empty updates log
    CdcrUpdateLog.CdcrLogReader reader = ((CdcrUpdateLog) ulog).newLogReader();
