@Test
public void testLogReaderSeek() throws Exception {
    this.clearCore();
    int start = 0;
    UpdateLog ulog = h.getCore().getUpdateHandler().getUpdateLog();
    CdcrUpdateLog.CdcrLogReader reader1 = ((CdcrUpdateLog) ulog).newLogReader();
