@Test
public void testRemoveOldLogs() throws Exception {
    this.clearCore();
    UpdateLog ulog = h.getCore().getUpdateHandler().getUpdateLog();
    File logDir = new File(h.getCore().getUpdateHandler().getUpdateLog().getLogDir());
    int start = 0;
    int maxReq = 50;
