    start += 105;
    assertJQ(req("qt", "/get", "getVersions", "" + maxReq), "/versions==" + versions.subList(0, Math.min(maxReq, start)));
    assertU(commit());
    assertJQ(req("qt", "/get", "getVersions", "" + maxReq), "/versions==" + versions.subList(0, Math.min(maxReq, start)));
    // previous tlogs should be gone now
    assertEquals(1, ulog.getLogList(logDir).length);
}

