@Test
public void testRemoveregex() throws Exception {
    SolrInputDocument doc;
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    doc.setField("cat", new String[] { "aaa", "bbb", "ccc", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "2");
    doc.setField("cat", new String[] { "aaa", "bbb", "bbb", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "20");
    doc.setField("cat", new String[] { "aaa", "ccc", "ddd" });
    assertU(adoc(doc));
    doc = new SolrInputDocument();
    doc.setField("id", "21");
    doc.setField("cat", new String[] { "aaa", "bbb", "ddd" });
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '3']");
    assertQ(req("q", "cat:ccc", "indent", "true"), "//result[@numFound = '3']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    List<String> removeList = new ArrayList<>();
    removeList.add(".b.");
    removeList.add("c+c");
    //behavior when hitting Solr through ZK
    doc.setField("cat", ImmutableMap.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '2']");
    // removeregex does remove all occurrences
    assertQ(req("q", "cat:ccc", "indent", "true"), "//result[@numFound = '2']");
    doc = new SolrInputDocument();
    doc.setField("id", "21");
    removeList = new ArrayList<>();
    removeList.add("bb*");
    removeList.add("cc+");
    //behavior when hitting Solr through ZK
    doc.setField("cat", ImmutableMap.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    //behavior when hitting Solr directly
    doc.setField("cat", ImmutableMap.of("removeregex", "a.a"));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:aaa", "indent", "true"), "//result[@numFound = '3']");
}

@Test
public void testRemoveregexMustMatchWholeValue() throws Exception {
    SolrInputDocument doc;
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    doc.setField("cat", new String[] { "aaa", "bbb", "ccc", "ccc", "ddd" });
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    List<String> removeList = new ArrayList<>();
    removeList.add("bb");
    //behavior when hitting Solr through ZK
    doc.setField("cat", ImmutableMap.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    // Was not removed - regex didn't match whole value
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
    doc = new SolrInputDocument();
    doc.setField("id", "1");
    removeList = new ArrayList<>();
    removeList.add("bbb");
    //behavior when hitting Solr through ZK
    doc.setField("cat", ImmutableMap.of("removeregex", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '1']");
    // Was removed now - regex matches
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '0']");
}

