@Test
public void testTimeCat() throws Exception {
    String configName = getSaferTestName();
    createConfigSet(configName);
    CreateTimeRoutedAlias TRA_Dim = createTimeRoutedAlias(getAlias(), "2019-07-01T00:00:00Z", "+1DAY", getTimeField(), null);
    CreateCategoryRoutedAlias CRA_Dim = createCategoryRoutedAlias(null, getCatField(), 20, null);
    CollectionAdminRequest.DimensionalRoutedAlias dra = CollectionAdminRequest.createDimensionalRoutedAlias(getAlias(), CollectionAdminRequest.createCollection("_unused_", configName, 2, 2).setMaxShardsPerNode(2), TRA_Dim, CRA_Dim);
    SolrParams params = dra.getParams();
    assertEquals("Dimensional[TIME,CATEGORY]", params.get(CollectionAdminRequest.RoutedAliasAdminRequest.ROUTER_TYPE_NAME));
    System.out.println(params);
    assertEquals("20", params.get("router.1.maxCardinality"));
    assertEquals("2019-07-01T00:00:00Z", params.get("router.0.start"));
    dra.process(solrClient);
    String firstCol = timeCatDraColFor("2019-07-01", CategoryRoutedAlias.UNINITIALIZED);
    cluster.waitForActiveCollection(firstCol, 2, 4);
    // cat field... har har.. get it? ... category/cat... ...oh never mind.
    addDocsAndCommit(true, newDoc("tabby", "2019-07-02T00:00:00Z"));
    assertCatTimeInvariants(ap(firstCol, // lower dimensions are fleshed out because we need to maintain the order of the TRA dim and
    // not fail if we get an older document later
    timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("tabby"));
    addDocsAndCommit(true, newDoc("calico", "2019-07-02T00:00:00Z"));
    // initial col not removed because the 07-01 CRA has not yet gained a new category (sub-dimensions are independent)
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("tabby", "calico"));
    testFailedDocument("shorthair", "2017-10-23T00:00:00Z", "couldn't be routed");
    testFailedDocument("shorthair", "2020-10-23T00:00:00Z", "too far in the future");
    testFailedDocument(null, "2019-07-02T00:00:00Z", "Route value is null");
    testFailedDocument("foo__CRA__bar", "2019-07-02T00:00:00Z", "7 character sequence __CRA__");
    testFailedDocument("fóóCRAóóbar", "2019-07-02T00:00:00Z", "7 character sequence __CRA__");
    // hopefully nothing changed
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("tabby", "calico"));
    // 4 docs no new collections
    addDocsAndCommit(true, newDoc("calico", "2019-07-02T00:00:00Z"), newDoc("tabby", "2019-07-01T00:00:00Z"), newDoc("tabby", "2019-07-01T23:00:00Z"), newDoc("calico", "2019-07-02T23:00:00Z"));
    // hopefully nothing changed
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("tabby", "calico"));
    // 4 docs 2 new collections, in random order and maybe not using the alias
    addDocsAndCommit(false, newDoc("calico", "2019-07-04T00:00:00Z"), newDoc("tabby", "2019-07-01T00:00:00Z"), newDoc("tabby", "2019-07-01T23:00:00Z"), newDoc("calico", "2019-07-03T23:00:00Z"));
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-03", "calico"), timeCatDraColFor("2019-07-04", "calico"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("tabby", "calico"));
    // now test with async pre-create.
    CollectionAdminRequest.setAliasProperty(getAlias()).addProperty("router.0.preemptiveCreateMath", "30MINUTE").process(solrClient);
    addDocsAndCommit(true, // create 2 sync 1 async
    newDoc("shorthair", "2019-07-02T23:40:00Z"), // does not create
    newDoc("calico", "2019-07-03T23:00:00Z"));
    waitColAndAlias(getAlias(), "", TRA + "2019-07-03" + CRA + "shorthair", 2);
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-03", "calico"), timeCatDraColFor("2019-07-04", "calico"), timeCatDraColFor("2019-07-01", "shorthair"), timeCatDraColFor("2019-07-02", "shorthair"), timeCatDraColFor("2019-07-03", "shorthair"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("shorthair", "tabby", "calico"));
    addDocsAndCommit(false, // should be no change
    newDoc("shorthair", "2019-07-02T23:40:00Z"), newDoc("calico", "2019-07-03T23:00:00Z"));
    /*
     Here we need to be testing that something that should not be created (extra preemptive async collections)
     didn't get created (a bug that actually got killed during development, and caused later asserts to
     fail due to wrong number of collections). There's no way to set a watch for something that doesn't and
     should never exist... Thus, the only choice is to sleep and make sure nothing appeared while we were asleep.
    */
    Thread.sleep(5000);
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-03", "calico"), timeCatDraColFor("2019-07-04", "calico"), timeCatDraColFor("2019-07-01", "shorthair"), timeCatDraColFor("2019-07-02", "shorthair"), timeCatDraColFor("2019-07-03", "shorthair"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("shorthair", "tabby", "calico"));
    // now test with auto-delete.
    CollectionAdminRequest.setAliasProperty(getAlias()).addProperty("router.0.autoDeleteAge", "/DAY-5DAY").process(solrClient);
    // this one should not yet cause deletion
    addDocsAndCommit(false, // no effect expected
    newDoc("shorthair", "2019-07-02T23:00:00Z"), // create 1
    newDoc("calico", "2019-07-05T23:00:00Z"));
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-01", "calico"), timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-03", "calico"), timeCatDraColFor("2019-07-04", "calico"), timeCatDraColFor("2019-07-05", "calico"), timeCatDraColFor("2019-07-01", "shorthair"), timeCatDraColFor("2019-07-02", "shorthair"), timeCatDraColFor("2019-07-03", "shorthair"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("shorthair", "tabby", "calico"));
    // have to only send to alias here since one of the collections will be deleted.
    addDocsAndCommit(true, // no effect expected
    newDoc("shorthair", "2019-07-02T23:00:00Z"), // create July 6, delete July 1
    newDoc("calico", "2019-07-06T00:00:00Z"));
    waitCoreCount(getAlias() + TRA + "2019-07-01" + CRA + "calico", 0);
    assertCatTimeInvariants(ap(timeCatDraColFor("2019-07-02", "calico"), timeCatDraColFor("2019-07-03", "calico"), timeCatDraColFor("2019-07-04", "calico"), timeCatDraColFor("2019-07-05", "calico"), timeCatDraColFor("2019-07-06", "calico"), // note that other categories are unaffected
    timeCatDraColFor("2019-07-01", "shorthair"), timeCatDraColFor("2019-07-02", "shorthair"), timeCatDraColFor("2019-07-03", "shorthair"), timeCatDraColFor("2019-07-01", "tabby"), timeCatDraColFor("2019-07-02", "tabby")), ap("shorthair", "tabby", "calico"));
    // verify that all the documents ended up in the right collections.
    QueryResponse resp = solrClient.query(getAlias(), params("q", "*:*", "rows", "100", "fl", "*,[shard]", "sort", "id asc"));
    SolrDocumentList results = resp.getResults();
    assertEquals(18, results.getNumFound());
    for (SolrDocument result : results) {
        String shard = String.valueOf(result.getFieldValue("[shard]"));
        String cat = String.valueOf(result.getFieldValue("cat_s"));
        Date date = (Date) result.getFieldValue("timestamp_dt");
        String day = date.toInstant().toString().split("T")[0];
        assertTrue(shard.contains(cat));
        assertTrue(shard.contains(day));
    }
}

