/**
 * @see #callComputeInPlaceUpdatableFields
 * @see AtomicUpdateDocumentMerger#computeInPlaceUpdatableFields
 */
@Test
public void testComputeInPlaceUpdatableFields() throws Exception {
    Set<String> inPlaceUpdatedFields = new HashSet<String>();
    // these asserts should hold true regardless of type, or wether the field has a default
    List<String> fieldsToCheck = Arrays.asList("inplace_updatable_float", "inplace_updatable_int", "inplace_updatable_float_with_default", "inplace_updatable_int_with_default");
    // ... and regardless of order checked
    Collections.shuffle(fieldsToCheck, random());
    for (String field : fieldsToCheck) {
        // In-place updatable field updated before it exists SHOULD NOW BE in-place updated (since LUCENE-8316):
        inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, field, map("set", 10)));
        assertTrue(field, inPlaceUpdatedFields.contains(field));
        // In-place updatable field updated after it exists SHOULD BE in-place updated:
        // setting up the dv
        addAndGetVersion(sdoc("id", "1", field, "0"), params());
        inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, field, map("set", 10)));
        assertTrue(field, inPlaceUpdatedFields.contains(field));
        inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, field, map("inc", 10)));
        assertTrue(field, inPlaceUpdatedFields.contains(field));
        final String altFieldWithDefault = field.contains("float") ? "inplace_updatable_int_with_default" : "inplace_updatable_int_with_default";
        // Updating an in-place updatable field (with a default) for the first time.
        // DV for it should have been already created when first document was indexed (above),
        // since it has a default value
        inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, altFieldWithDefault, map("set", 10)));
        assertTrue(field + " -> " + altFieldWithDefault, inPlaceUpdatedFields.contains(altFieldWithDefault));
        deleteAllAndCommit();
    }
    // Non in-place updates
    // setting up the dv
    addAndGetVersion(sdoc("id", "1", "stored_i", "0"), params());
    assertTrue("stored field updated", callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, "stored_i", map("inc", 1))).isEmpty());
    assertTrue("full document update", callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, "inplace_updatable_int_with_default", "100")).isEmpty());
    assertFalse("non existent dynamic dv field updated first time", callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, "new_updatable_int_i_dvo", map("set", 10))).isEmpty());
    // After adding a full document with the dynamic dv field, in-place update should work
    // setting up the dv
    addAndGetVersion(sdoc("id", "2", "new_updatable_int_i_dvo", "0"), params());
    if (random().nextBoolean()) {
        assertU(commit("softCommit", "false"));
    }
    inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "2", "_version_", 42L, "new_updatable_int_i_dvo", map("set", 10)));
    assertTrue(inPlaceUpdatedFields.contains("new_updatable_int_i_dvo"));
    // for copy fields, regardless of whether the source & target support inplace updates,
    // it won't be inplace if the DVs don't exist yet...
    assertTrue("inplace fields should be empty when doc has no copyfield src values yet", callComputeInPlaceUpdatableFields(sdoc("id", "1", "_version_", 42L, "copyfield1_src__both_updatable", map("set", 1), "copyfield2_src__only_src_updatable", map("set", 2))).isEmpty());
    // now add a doc that *does* have the src field for each copyfield...
    addAndGetVersion(sdoc("id", "3", "copyfield1_src__both_updatable", -13, "copyfield2_src__only_src_updatable", -15), params());
    if (random().nextBoolean()) {
        assertU(commit("softCommit", "false"));
    }
    // If a supported dv field has a copyField target which is supported, it should be an in-place update
    inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "3", "_version_", 42L, "copyfield1_src__both_updatable", map("set", 10)));
    assertTrue(inPlaceUpdatedFields.contains("copyfield1_src__both_updatable"));
    // If a supported dv field has a copyField target which is not supported, it should not be an in-place update
    inPlaceUpdatedFields = callComputeInPlaceUpdatableFields(sdoc("id", "3", "_version_", 42L, "copyfield2_src__only_src_updatable", map("set", 10)));
    assertTrue(inPlaceUpdatedFields.isEmpty());
}

@Test
public /**
 *  Test the @see {@link AtomicUpdateDocumentMerger#doInPlaceUpdateMerge(AddUpdateCommand,Set<String>)}
 *  method is working fine
 */
void testDoInPlaceUpdateMerge() throws Exception {
    long version1 = addAndGetVersion(sdoc("id", "1", "title_s", "first"), null);
    long version2 = addAndGetVersion(sdoc("id", "2", "title_s", "second"), null);
    long version3 = addAndGetVersion(sdoc("id", "3", "title_s", "third"), null);
    assertU(commit("softCommit", "false"));
    assertQ(req("q", "*:*"), "//*[@numFound='3']");
    // Adding a few in-place updates
    version1 = addAndAssertVersion(version1, "id", "1", "inplace_updatable_float", map("set", 200));
    // Test the AUDM.doInPlaceUpdateMerge() method is working fine
    try (SolrQueryRequest req = req()) {
        AddUpdateCommand cmd = buildAddUpdateCommand(req, sdoc("id", "1", "_version_", 42L, "inplace_updatable_float", map("inc", 10)));
        AtomicUpdateDocumentMerger docMerger = new AtomicUpdateDocumentMerger(req);
        assertTrue(docMerger.doInPlaceUpdateMerge(cmd, AtomicUpdateDocumentMerger.computeInPlaceUpdatableFields(cmd)));
        assertEquals(42L, cmd.getSolrInputDocument().getFieldValue("_version_"));
        assertEquals(42L, cmd.getSolrInputDocument().getFieldValue("_version_"));
        assertEquals(210f, cmd.getSolrInputDocument().getFieldValue("inplace_updatable_float"));
        // in-place merged doc shouldn't have non-inplace fields from the index/tlog
        assertFalse(cmd.getSolrInputDocument().containsKey("title_s"));
        assertEquals(version1, cmd.prevVersion);
    }
    // do a commit, and the same results should be repeated
    assertU(commit("softCommit", "false"));
    // Test the AUDM.doInPlaceUpdateMerge() method is working fine
    try (SolrQueryRequest req = req()) {
        AddUpdateCommand cmd = buildAddUpdateCommand(req, sdoc("id", "1", "_version_", 42L, "inplace_updatable_float", map("inc", 10)));
        AtomicUpdateDocumentMerger docMerger = new AtomicUpdateDocumentMerger(req);
        assertTrue(docMerger.doInPlaceUpdateMerge(cmd, AtomicUpdateDocumentMerger.computeInPlaceUpdatableFields(cmd)));
        assertEquals(42L, cmd.getSolrInputDocument().getFieldValue("_version_"));
        assertEquals(42L, cmd.getSolrInputDocument().getFieldValue("_version_"));
        assertEquals(210f, cmd.getSolrInputDocument().getFieldValue("inplace_updatable_float"));
        // in-place merged doc shouldn't have non-inplace fields from the index/tlog
        assertFalse(cmd.getSolrInputDocument().containsKey("title_s"));
        assertEquals(version1, cmd.prevVersion);
    }
}

@Test
public void testUpdatingDocValuesWithRouteField() throws Exception {
    new UpdateRequest().deleteByQuery("*:*").commit(cluster.getSolrClient(), COLLECTION);
    new UpdateRequest().add(createDocs(NUMBER_OF_DOCS)).commit(cluster.getSolrClient(), COLLECTION);
    int id = TestUtil.nextInt(random(), 1, NUMBER_OF_DOCS - 1);
    SolrDocument solrDocument = queryDoc(id);
    Long initialVersion = (Long) solrDocument.get("_version_");
    Integer luceneDocId = (Integer) solrDocument.get("[docid]");
    String shardName = (String) solrDocument.get("shardName");
    Assert.assertThat(solrDocument.get("inplace_updatable_int"), is(id));
    int newDocValue = TestUtil.nextInt(random(), 1, 2 * NUMBER_OF_DOCS - 1);
    SolrInputDocument sdoc = sdoc("id", "" + id, // use route field in update command
    "shardName", shardName, "inplace_updatable_int", map("set", newDocValue));
    UpdateRequest updateRequest = new UpdateRequest().add(sdoc);
    updateRequest.commit(cluster.getSolrClient(), COLLECTION);
    solrDocument = queryDoc(id);
    Long newVersion = (Long) solrDocument.get("_version_");
    Assert.assertTrue("Version of updated document must be greater than original one", newVersion > initialVersion);
    Assert.assertThat("Doc value must be updated", solrDocument.get("inplace_updatable_int"), is(newDocValue));
    Assert.assertThat("Lucene doc id should not be changed for In-Place Updates.", solrDocument.get("[docid]"), is(luceneDocId));
    try {
        sdoc.remove("shardName");
        new UpdateRequest().add(sdoc).process(cluster.getSolrClient(), COLLECTION);
        fail("expect  an exception w/o route field");
    } catch (SolrException ex) {
        assertThat("expecting 400 in " + ex.getMessage(), ex.code(), is(400));
    }
}

