        AddUpdateCommand updateCommand = new AddUpdateCommand(null);
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("uuid", uuid);
        updateCommand.solrDoc = doc;
        tlog.write(updateCommand);
