@Test
public void testProcessUrl() throws Exception {
    DriverImpl driver = new DriverImpl();
    List<String> zkHostStrings = Arrays.asList("zoo1", "zoo1:9983", "zoo1,zoo2,zoo3", "zoo1:9983,zoo2:9983,zoo3:9983");
