        assertEquals("a", tuples.get(1).get("a_ss"));
        assertEquals(2L, tuples.get(1).get("b_ls"));
        assertEquals("a", tuples.get(2).get("a_ss"));
        assertEquals(3L, tuples.get(2).get("b_ls"));
