@Test
public void testMultiCollection() throws Exception {
    CollectionAdminRequest.createCollection("collection2", "conf", 2, 1).process(cluster.getSolrClient());
    cluster.waitForActiveCollection("collection2", 2, 2);
    new UpdateRequest().add(id, "0", "a_s", "hello", "a_i", "0", "a_f", "0", "s_multi", "aaaa", "test_dt", getDateString("2016", "5", "1"), "i_multi", "4", "i_multi", "7").add(id, "2", "a_s", "hello", "a_i", "2", "a_f", "0", "s_multi", "aaaa1", "test_dt", getDateString("2016", "5", "1"), "i_multi", "44", "i_multi", "77").add(id, "3", "a_s", "hello", "a_i", "3", "a_f", "3", "s_multi", "aaaa2", "test_dt", getDateString("2016", "5", "1"), "i_multi", "444", "i_multi", "777").add(id, "4", "a_s", "hello", "a_i", "4", "a_f", "4", "s_multi", "aaaa3", "test_dt", getDateString("2016", "5", "1"), "i_multi", "4444", "i_multi", "7777").add(id, "1", "a_s", "hello", "a_i", "1", "a_f", "1", "s_multi", "aaaa4", "test_dt", getDateString("2016", "5", "1"), "i_multi", "44444", "i_multi", "77777").commit(cluster.getSolrClient(), "collection1");
    new UpdateRequest().add(id, "10", "a_s", "hello", "a_i", "10", "a_f", "0", "s_multi", "aaaa", "test_dt", getDateString("2016", "5", "1"), "i_multi", "4", "i_multi", "7").add(id, "12", "a_s", "hello", "a_i", "12", "a_f", "0", "s_multi", "aaaa1", "test_dt", getDateString("2016", "5", "1"), "i_multi", "44", "i_multi", "77").add(id, "13", "a_s", "hello", "a_i", "13", "a_f", "3", "s_multi", "aaaa2", "test_dt", getDateString("2016", "5", "1"), "i_multi", "444", "i_multi", "777").add(id, "14", "a_s", "hello", "a_i", "14", "a_f", "4", "s_multi", "aaaa3", "test_dt", getDateString("2016", "5", "1"), "i_multi", "4444", "i_multi", "7777").add(id, "11", "a_s", "hello", "a_i", "11", "a_f", "1", "s_multi", "aaaa4", "test_dt", getDateString("2016", "5", "1"), "i_multi", "44444", "i_multi", "77777").commit(cluster.getSolrClient(), "collection2");
    List<Tuple> tuples;
    StreamContext streamContext = new StreamContext();
    SolrClientCache solrClientCache = new SolrClientCache();
    streamContext.setSolrClientCache(solrClientCache);
    List<String> shardUrls = TupleStream.getShards(cluster.getZkServer().getZkAddress(), COLLECTIONORALIAS, streamContext);
    try {
        StringBuilder buf = new StringBuilder();
        for (String shardUrl : shardUrls) {
            if (buf.length() > 0) {
                buf.append(",");
            }
            buf.append(shardUrl);
        }
        ModifiableSolrParams solrParams = new ModifiableSolrParams();
        solrParams.add("qt", "/stream");
        solrParams.add("expr", "search(\"collection1, collection2\", q=\"*:*\", fl=\"id, a_i\", rows=50, sort=\"a_i asc\")");
        SolrStream solrStream = new SolrStream(shardUrls.get(0), solrParams);
        solrStream.setStreamContext(streamContext);
        tuples = getTuples(solrStream);
        assert (tuples.size() == 10);
        assertOrder(tuples, 0, 1, 2, 3, 4, 10, 11, 12, 13, 14);
        //Test with export handler, different code path.
        solrParams = new ModifiableSolrParams();
        solrParams.add("qt", "/stream");
        solrParams.add("expr", "search(\"collection1, collection2\", q=\"*:*\", fl=\"id, a_i\", sort=\"a_i asc\", qt=\"/export\")");
        solrStream = new SolrStream(shardUrls.get(0), solrParams);
        solrStream.setStreamContext(streamContext);
        tuples = getTuples(solrStream);
        assert (tuples.size() == 10);
        assertOrder(tuples, 0, 1, 2, 3, 4, 10, 11, 12, 13, 14);
        solrParams = new ModifiableSolrParams();
        solrParams.add("qt", "/stream");
        solrParams.add("expr", "facet(\"collection1, collection2\", q=\"*:*\", buckets=\"a_s\", bucketSorts=\"count(*) asc\", count(*))");
        solrStream = new SolrStream(shardUrls.get(0), solrParams);
        solrStream.setStreamContext(streamContext);
        tuples = getTuples(solrStream);
        assert (tuples.size() == 1);
        Tuple tuple = tuples.get(0);
        assertEquals(tuple.getString("a_s"), "hello");
        assertEquals(tuple.getLong("count(*)").longValue(), 10);
        String expr = "timeseries(\"collection1, collection2\", q=\"*:*\", " + "start=\"2016-01-01T01:00:00.000Z\", " + "end=\"2016-12-01T01:00:00.000Z\", " + "gap=\"+1YEAR\", " + "field=\"test_dt\", " + "format=\"yyyy\"," + "count(*))";
        solrParams = new ModifiableSolrParams();
        solrParams.add("qt", "/stream");
        solrParams.add("expr", expr);
        solrStream = new SolrStream(shardUrls.get(0), solrParams);
        solrStream.setStreamContext(streamContext);
        tuples = getTuples(solrStream);
        assert (tuples.size() == 1);
        tuple = tuples.get(0);
        assertEquals(tuple.getString("test_dt"), "2016");
        assertEquals(tuple.getLong("count(*)").longValue(), 10);
        //Test parallel
        solrParams = new ModifiableSolrParams();
        solrParams.add("qt", "/stream");
        solrParams.add("expr", "parallel(collection1, sort=\"a_i asc\", workers=2, search(\"collection1, collection2\", q=\"*:*\", fl=\"id, a_i\", sort=\"a_i asc\", qt=\"/export\", partitionKeys=\"a_s\"))");
        solrStream = new SolrStream(shardUrls.get(0), solrParams);
        solrStream.setStreamContext(streamContext);
        tuples = getTuples(solrStream);
        assert (tuples.size() == 10);
        assertOrder(tuples, 0, 1, 2, 3, 4, 10, 11, 12, 13, 14);
    } finally {
        CollectionAdminRequest.deleteCollection("collection2").process(cluster.getSolrClient());
        solrClientCache.close();
    }
}

