    // use FS factory
    useFactory(null);
    try {
        cores = CoreContainer.createAndLoad(SOLR_HOME, getSolrXml());
        String ddir = CoreAdminRequest.getCoreStatus("core0", getSolrCore0()).getDataDirectory();
        Path data = Paths.get(ddir, "index");
