public void testStrictPositive() throws IOException {
    assertEquals(O("foo", "bar", "ban", "buzz"), ObjectBuilder.fromJSONStrict("{\"foo\":\"bar\", \"ban\":\"buzz\"}"));
    assertEquals(O("foo", "bar"), ObjectBuilder.fromJSONStrict("{\"foo\":\"bar\"/*, \"ban\":\"buzz\"*/}"));
    assertEquals(O("foo", "bar"), ObjectBuilder.fromJSONStrict("{\"foo\":\"bar\"} /*\"ban\":\"buzz\"*/"));
    assertEquals("foo", ObjectBuilder.fromJSONStrict("\"foo\""));
    assertEquals("fromJSON() ignores tail.", O("foo", "bar"), ObjectBuilder.fromJSON("{\"foo\":\"bar\"} \"ban\":\"buzz\"}"));
    assertEquals("old method ignores tails", "foo", ObjectBuilder.fromJSON("\"foo\" \"baar\" "));
    expectThrows(ParseException.class, () -> ObjectBuilder.fromJSONStrict("\"foo\" \"bar\""));
    expectThrows(ParseException.class, () -> ObjectBuilder.fromJSONStrict("{\"foo\":\"bar\"} \"ban\":\"buzz\"}"));
    expectThrows(ParseException.class, () -> ObjectBuilder.getValStrict(new JSONParser("{\"foo\":\"bar\"} \"ban\":\"buzz\"}")));
    expectThrows(ParseException.class, () -> new ObjectBuilder(new JSONParser("{\"foo\":\"bar\"} \"ban\":\"buzz\"}")).getValStrict());
}

@Test
public void testRestartPorts() throws Exception {
    Path solrHome = createTempDir();
    Files.write(solrHome.resolve("solr.xml"), MiniSolrCloudCluster.DEFAULT_CLOUD_SOLR_XML.getBytes(Charset.defaultCharset()));
    JettyConfig config = JettyConfig.builder().build();
    JettySolrRunner jetty = new JettySolrRunner(solrHome.toString(), config);
    try {
        jetty.start();
        URL url = jetty.getBaseUrl();
        int usedPort = url.getPort();
        jetty.stop();
        jetty.start();
        assertEquals("After restart, jetty port should be the same", usedPort, jetty.getBaseUrl().getPort());
        jetty.stop();
        jetty.start(false);
        assertThat("After restart, jetty port should be different", jetty.getBaseUrl().getPort(), not(usedPort));
    } finally {
        if (jetty.isRunning())
            jetty.stop();
    }
}

